  '{{route}} · {{vehicle}} starts now as if it left the first stop. Normally the trip starts by itself when the vehicle leaves the start stop.': '{{route}} · {{vehicle}} முதல் நிறுத்தத்திலிருந்து புறப்பட்டது போல இப்போது தொடங்கும். வழக்கமாக வாகனம் தொடக்க நிறுத்தத்திலிருந்து புறப்படும்போது பயணம் தானாகவே தொடங்கும்.',
