  'Acknowledge {{target}}. The note is saved with each alert.': '{{target}} ஒப்புக்கொள். குறிப்பு ஒவ்வொரு எச்சரிக்கையுடனும் சேமிக்கப்படும்.',
  'Acknowledge & view': 'ஒப்புக்கொண்டு பார்',
