  'Acknowledge shown alerts': 'காட்டப்படும் எச்சரிக்கைகளை ஒப்புக்கொள்',
  'Acknowledge the alerts shown that need it': 'காட்டப்படும் எச்சரிக்கைகளில் ஒப்புதல் தேவையானவற்றை ஒப்புக்கொள்',
  'Acknowledge the unread alerts shown': 'காட்டப்படும் படிக்காத எச்சரிக்கைகளை ஒப்புக்கொள்',
  'Acknowledge, escalate and close incidents.': 'சம்பவங்களை ஏற்க, மேலனுப்ப மற்றும் மூடலாம்.',
