  'Actions for {{name}}': '{{name}} க்கான செயல்கள்',
  'Activate': 'செயல்படுத்து',
  'Activate {{n}} record(s)?': '{{n}} பதிவு(களை) செயல்படுத்தவா?',
  'Activate or deactivate groups from the list\'s bulk actions.': 'பட்டியலின் மொத்த செயல்களிலிருந்து குழுக்களைச் செயல்படுத்தவும் அல்லது செயலிழக்கச் செய்யவும்.',
  'activated {{time}}': '{{time}} அன்று செயல்படுத்தப்பட்டது',
  'Activation code': 'செயல்படுத்தும் குறியீடு',
  'Activation codes will also be e-mailed to {{email}}.': 'செயல்படுத்தும் குறியீடுகள் {{email}} க்கும் மின்னஞ்சல் செய்யப்படும்.',
  'Active': 'செயலில்',
  'Active {{window}} (company timezone)': 'செயலில் {{window}} (நிறுவன நேர மண்டலம்)',
  'Active all the time': 'எப்போதும் செயலில்',
  'Active hours': 'செயலில் உள்ள நேரம்',
  'Active issues': 'செயலில் உள்ள சிக்கல்கள்',
  'Active links': 'செயலில் உள்ள இணைப்புகள்',
  'Active schedules with a vehicle create planned trips on the chosen days, {{h}} h ahead (company timezone).': 'வாகனம் உள்ள செயலில் உள்ள அட்டவணைகள் தேர்ந்தெடுத்த நாட்களில் {{h}} மணி நேரம் முன்னதாகத் திட்டமிட்ட பயணங்களை உருவாக்கும் (நிறுவன நேர மண்டலம்).',
  'Active, inactive, no-GPS and never-connected devices right now.': 'தற்போது செயலில், செயலற்ற, GPS இல்லாத மற்றும் ஒருபோதும் இணைக்கப்படாத சாதனங்கள்.',
  'Activity': 'செயல்பாடு',
  'Actual': 'உண்மையானது',
  'Actual end': 'உண்மையான முடிவு',
  'Actual km': 'உண்மையான km',
  'Actual start': 'உண்மையான தொடக்கம்',
  'Actual start / end': 'உண்மையான தொடக்கம் / முடிவு',
  'Add': 'சேர்',
  'Add a schedule to create trips on this route automatically. You can also create single trips under Planned trips.': 'இந்த வழித்தடத்தில் தானாகப் பயணங்களை உருவாக்க அட்டவணையைச் சேர்க்கவும். திட்டமிட்ட பயணங்கள் பகுதியில் தனிப் பயணங்களையும் உருவாக்கலாம்.',
  'Add a time window, or switch parking mode off': 'நேர இடைவெளியைச் சேர்க்கவும், அல்லது பார்க்கிங் பயன்முறையை அணைக்கவும்',
  'Add a tracker': 'டிராக்கரைச் சேர்',
  'Add an endpoint to receive alerts, trips and status changes in real time.': 'எச்சரிக்கைகள், பயணங்கள் மற்றும் நிலை மாற்றங்களை உடனுக்குடன் பெற ஒரு எண்ட்பாயிண்டைச் சேர்க்கவும்.',
  'Add another': 'மேலும் ஒன்றைச் சேர்',
  'Add at least one more stop: a route needs a start and an end.': 'குறைந்தது இன்னொரு நிறுத்தத்தைச் சேர்க்கவும்: வழித்தடத்துக்குத் தொடக்கமும் முடிவும் தேவை.',
  'Add at least one recipient': 'குறைந்தது ஒரு பெறுநரைச் சேர்க்கவும்',
