  'Add vehicles under Masters → Objects first.': 'முதலில் மாஸ்டர்கள் → பொருட்கள் பகுதியில் வாகனங்களைச் சேர்க்கவும்.',
  'Add webhook': 'வெப்ஹூக் சேர்',
  'Add what you want to track: it starts on a free trial (phones 100 days, GPS trackers and dashcams 30 days). Buy a yearly licence before the trial ends.': 'கண்காணிக்க வேண்டியதைச் சேர்க்கவும்: இது இலவச சோதனையுடன் தொடங்கும் (ஃபோன் 100 நாட்கள், GPS டிராக்கர் மற்றும் டேஷ்கேம் 30 நாட்கள்). சோதனை முடிவதற்குள் வருடாந்திர உரிமம் வாங்கவும்.',
  'Add what you want to track. Each tracker or phone needs a yearly licence.': 'நீங்கள் கண்காணிக்க விரும்புவதைச் சேர்க்கவும். ஒவ்வொரு டிராக்கர் அல்லது தொலைபேசிக்கும் ஆண்டு உரிமம் தேவை.',
  'Add-ons': 'கூடுதல் வசதிகள்',
  'Added to device timestamps.': 'சாதன நேரமுத்திரைகளில் சேர்க்கப்படும்.',
  'Added. Install VeeTrax Tracker on that phone and activate it with the same number.': 'சேர்க்கப்பட்டது. அந்தத் தொலைபேசியில் VeeTrax Tracker-ஐ நிறுவி அதே எண்ணுடன் செயல்படுத்தவும்.',
  'Address': 'முகவரி',
  'Address hidden for your role': 'உங்கள் பங்கிற்கு முகவரி மறைக்கப்பட்டுள்ளது',
  'Address match is uncertain': 'முகவரிப் பொருத்தம் உறுதியில்லை',
  'Address matches': 'பொருந்தும் முகவரிகள்',
  'Address not available': 'முகவரி கிடைக்கவில்லை',
  'Address not found': 'முகவரி கிடைக்கவில்லை',
  'Address pending': 'முகவரி நிலுவையில்',
  'Adds comparisons with the previous period and the team, pattern charts, the 12-month trend, periods up to 6 months and PNG / PDF download to Staff attendance → Employee.': 'பணியாளர் வருகை → ஊழியர் பகுதியில் முந்தைய காலம் மற்றும் குழுவுடன் ஒப்பீடு, முறை வரைபடங்கள், 12 மாதப் போக்கு, 6 மாதங்கள் வரையிலான காலம் மற்றும் PNG / PDF பதிவிறக்கத்தைச் சேர்க்கிறது.',
  'Adds the Employee transport menus (agreements, transport settings). Switching it on also creates the Transport admin, dispatcher, passenger and driver roles once. Switching it off hides the menus; data is kept.': 'ஊழியர் போக்குவரத்து மெனுக்களை (ஒப்பந்தங்கள், போக்குவரத்து அமைப்புகள்) சேர்க்கிறது. இயக்கும்போது போக்குவரத்து நிர்வாகி, அனுப்புநர், பயணி, ஓட்டுநர் பங்குகள் ஒருமுறை உருவாக்கப்படும். நிறுத்தினால் மெனுக்கள் மறைக்கப்படும்; தரவு வைக்கப்படும்.',
  'Admin on behalf': 'சார்பாக நிர்வாகி',
  'Administration': 'நிர்வாகம்',
  'Admins of this company see the reseller pool in Billing & Licences.': 'இந்த நிறுவனத்தின் நிர்வாகிகள் பில்லிங் & உரிமங்களில் மறுவிற்பனையாளர் தொகுப்பைப் பார்ப்பார்கள்.',
  'Advanced attendance insights': 'மேம்பட்ட வருகை பகுப்பாய்வு',
  'Advanced attendance insights add comparisons with the previous period and the team, late-by-weekday and time-away charts, the daily in / out chart, the 12-month trend, periods up to 6 months and PDF download. Ask VeeTrax support to turn them on for your company.': 'மேம்பட்ட வருகை பகுப்பாய்வில் முந்தைய காலம் மற்றும் குழுவுடன் ஒப்பீடு, வாரநாள் வாரியான தாமதம் மற்றும் வெளியே இருந்த நேர வரைபடங்கள், தினசரி வருகை / வெளியேற்ற வரைபடம், 12 மாதப் போக்கு, 6 மாதங்கள் வரையிலான காலம் மற்றும் PDF பதிவிறக்கம் கிடைக்கும். உங்கள் நிறுவனத்திற்கு இயக்க VeeTrax ஆதரவைத் தொடர்பு கொள்ளவும்.',
