  'Alarms ring in this browser while a VeeTrax tab is open. On phones, open the VeeTrax app once and allow alarms to override Do Not Disturb (More → Parking mode → Alarm on this phone).': 'VeeTrax தாவல் திறந்திருக்கும்போது இந்த உலாவியில் அலாரம் ஒலிக்கும். தொலைபேசியில் VeeTrax செயலியை ஒருமுறை திறந்து, தொந்தரவு செய்யாதே பயன்முறையைத் தாண்ட அலாரத்தை அனுமதிக்கவும் (மேலும் → பார்க்கிங் பயன்முறை → இந்தத் தொலைபேசியில் அலாரம்).',
