  'Alert type': 'எச்சரிக்கை வகை',
  'Alert types': 'எச்சரிக்கை வகைகள்',
  'Alert when a stop is reached later than plan by more than': 'நிறுத்தத்தைத் திட்டமிட்ட நேரத்தைவிட இதற்கு மேல் தாமதமாக அடைந்தால் எச்சரிக்கை',
  'Alert when a vehicle stays longer': 'வாகனம் அதிக நேரம் தங்கினால் எச்சரிக்கை',
  'Alert when data arrives later than': 'தரவு இதைவிட தாமதமாக வந்தால் எச்சரிக்கை',
  'Alert when not started this long after the planned start': 'திட்டமிட்ட தொடக்கத்துக்குப் பிறகு இவ்வளவு நேரம் தொடங்காவிட்டால் எச்சரிக்கை',
  'Alert when off the planned path by more than': 'திட்டமிட்ட பாதையிலிருந்து இதற்கு மேல் விலகினால் எச்சரிக்கை',
  'Alert when the device clock is ahead by': 'சாதனக் கடிகாரம் இவ்வளவு முன்னால் இருந்தால் எச்சரிக்கை',
  'Alert when the door is open above': 'இந்த வேகத்திற்கு மேல் கதவு திறந்திருந்தால் எச்சரிக்கை',
  'Alerts': 'எச்சரிக்கைகள்',
  'Alerts appear here as soon as vehicles trigger them.': 'வாகனங்கள் தூண்டியவுடன் எச்சரிக்கைகள் இங்கே தோன்றும்.',
  'Alerts matching these filters will appear here.': 'இந்த வடிகட்டிகளுக்குப் பொருந்தும் எச்சரிக்கைகள் இங்கே தோன்றும்.',
  'Alerts of the last 24 hours': 'கடந்த 24 மணிநேர எச்சரிக்கைகள்',
  'Alerts raised for the vehicles.': 'வாகனங்களுக்கு எழுப்பப்பட்ட எச்சரிக்கைகள்.',
  'Alerts raised in the period with severity and status; filter by type.': 'காலத்தில் எழுந்த எச்சரிக்கைகள் தீவிரம் மற்றும் நிலையுடன்; வகைப்படி வடிகட்டவும்.',
  'Alerts ranking': 'எச்சரிக்கை தரவரிசை',
  'Alerts that still need acknowledgement': 'இன்னும் ஒப்புதல் தேவைப்படும் எச்சரிக்கைகள்',
  'Alerts today': 'இன்றைய எச்சரிக்கைகள்',
  'Alerts today by type': 'வகைப்படி இன்றைய எச்சரிக்கைகள்',
  'Alerts, {{count}} unread': 'எச்சரிக்கைகள், {{count}} படிக்காதவை',
  'Alerts: "Staff not arrived" after start + grace, "Staff absent" at the end of the shift, "Staff left work site" when someone is out during the shift for longer than a short exit, and "Staff still out" after the time above. Choose who gets them in Alert Settings.': 'எச்சரிக்கைகள்: தொடக்கம் + சலுகைக்குப் பிறகு "பணியாளர் வரவில்லை", ஷிப்ட் முடிவில் "பணியாளர் வரவில்லை (விடுப்பு)", ஷிப்ட்டின் போது குறுகிய வெளியேற்றத்தை விட அதிக நேரம் வெளியே இருந்தால் "பணியாளர் பணியிடத்தை விட்டு வெளியேறினார்", மேலே உள்ள நேரத்திற்குப் பிறகு "பணியாளர் இன்னும் வெளியே உள்ளார்". யாருக்கு அனுப்புவது என்பதை எச்சரிக்கை அமைப்புகளில் தேர்வுசெய்யவும்.',
  'Alerts: "Staff not arrived" when nobody has reached a work site by start + grace, and "Staff absent" at the end of the working day. Choose who gets them in Alert Settings.': 'எச்சரிக்கைகள்: தொடக்கம் + சலுகை நேரத்துக்குள் பணித்தளம் வரவில்லை எனில் "பணியாளர் வரவில்லை", வேலை நாள் முடிவில் "பணியாளர் வருகை இல்லை". யாருக்குச் செல்ல வேண்டும் என எச்சரிக்கை அமைப்புகளில் தேர்ந்தெடுக்கவும்.',
  'All': 'அனைத்தும்',
  'All {{count}} stops': 'அனைத்து {{count}} நிறுத்தங்களும்',
  'All {{label}}': 'அனைத்து {{label}}',
  'all actions': 'அனைத்து செயல்கள்',
