  'All clear: nothing needs attention right now.': 'எல்லாம் சரி: இப்போது எதற்கும் கவனம் தேவையில்லை.',
  'All companies': 'அனைத்து நிறுவனங்கள்',
  'All companies: the live map and the Vehicles, Devices and Drivers lists show every company. Other pages show your own company. To add or edit, choose a company.': 'அனைத்து நிறுவனங்கள்: நேரடி வரைபடமும் வாகனங்கள், சாதனங்கள், ஓட்டுநர்கள் பட்டியல்களும் ஒவ்வொரு நிறுவனத்தையும் காட்டும். மற்ற பக்கங்கள் உங்கள் சொந்த நிறுவனத்தைக் காட்டும். சேர்க்க அல்லது திருத்த, ஒரு நிறுவனத்தைத் தேர்ந்தெடுக்கவும்.',
  'All customer sites.': 'எல்லா வாடிக்கையாளர் தளங்களும்.',
