  'All forwarding is paused': 'அனைத்து அனுப்புதலும் நிறுத்தி வைக்கப்பட்டுள்ளது',
  'All forwarding paused': 'அனைத்து அனுப்புதலும் நிறுத்தப்பட்டது',
  'All groups': 'அனைத்து குழுக்கள்',
  'All new alerts acknowledged': 'அனைத்து புதிய எச்சரிக்கைகளும் ஒப்புக்கொள்ளப்பட்டன',
