  'All passengers have an outcome.': 'எல்லா பயணிகளுக்கும் முடிவு பதிவாகியுள்ளது.',
  'All points': 'அனைத்துப் புள்ளிகள்',
  'All processes, ports, queues and stores are healthy.': 'அனைத்து செயல்முறைகள், போர்ட்கள், வரிசைகள் மற்றும் சேமிப்புகள் நலமாக உள்ளன.',
  'All routes': 'அனைத்து வழித்தடங்கள்',
  'All severities': 'அனைத்து தீவிரங்கள்',
