  'Allocate': 'ஒதுக்கு',
  'Allocate licences to {{name}}': '{{name}} க்கு உரிமங்களை ஒதுக்கு',
  'Allow anyway': 'இருந்தும் அனுமதி',
  'Allow full-screen SOS alerts': 'முழுத்திரை SOS எச்சரிக்கைகளை அனுமதி',
  'Allow location “All the time”: tracking keeps running in the background until Stop is tapped.': 'இருப்பிடத்தை “எப்போதும்” அனுமதிக்கவும்: Stop அழுத்தும் வரை கண்காணிப்பு பின்னணியில் தொடரும்.',
  'Allow the camera to photograph the bill.': 'ரசீதைப் படமெடுக்க கேமராவை அனுமதிக்கவும்.',
  'Allow through Do Not Disturb': 'தொந்தரவு செய்ய வேண்டாம் பயன்முறையிலும் அனுமதி',
  'Allowed IP addresses': 'அனுமதிக்கப்பட்ட IP முகவரிகள்',
  'Allows this one create with a short complimentary licence. Recorded in the audit log.': 'குறுகிய இலவச உரிமத்துடன் இந்த ஒரு உருவாக்கத்தை அனுமதிக்கும். தணிக்கைப் பதிவில் சேமிக்கப்படும்.',
  'Already have an account? Sign in': 'ஏற்கனவே கணக்கு உள்ளதா? உள்நுழையவும்',
  'Also {{min}} with no phone signal (not counted as away).': 'மேலும் {{min}} போன் சிக்னல் இல்லை (வெளியே என்று கணக்கிடப்படவில்லை).',
  'Also allow engine stop / restore. Refused while the vehicle moves.': 'என்ஜின் நிறுத்தம் / மீட்டமைப்பையும் அனுமதி. வாகனம் நகரும்போது மறுக்கப்படும்.',
  'Also cancel their bookings (otherwise they go back to the queue to be seated again).': 'அவர்களின் முன்பதிவுகளையும் ரத்து செய் (இல்லையெனில் மீண்டும் இருக்கை பெற வரிசைக்குத் திரும்பும்).',
  'Also end maintenance for this vehicle (alerts resume)': 'இந்த வாகனத்தின் பராமரிப்பையும் முடிக்கவும் (எச்சரிக்கைகள் மீண்டும் தொடங்கும்)',
  'Also has other roles': 'பிற பங்குகளும் உள்ளன',
  'Always': 'எப்போதும்',
  'Always active': 'எப்போதும் செயலில்',
  'Always active. Add a window to limit when this geofence raises alerts.': 'எப்போதும் செயலில். இந்த ஜியோஃபென்ஸ் எப்போது எச்சரிக்கை எழுப்பும் என்பதை வரம்பிட நேர இடைவெளியைச் சேர்க்கவும்.',
  'Always required for SOS and crash alerts': 'SOS மற்றும் விபத்து எச்சரிக்கைகளுக்கு எப்போதும் தேவை',
  'Amount': 'தொகை',
  'Amount (₹)': 'தொகை (₹)',
  'An existing login of your company was linked. That person keeps their other roles.': 'உங்கள் நிறுவனத்தின் தற்போதைய உள்நுழைவு இணைக்கப்பட்டது. அந்த நபரின் பிற பங்குகள் தொடரும்.',
  'An invoice is issued and e-mailed for every payment.': 'ஒவ்வொரு கட்டணத்திற்கும் விலைப்பட்டியல் வழங்கப்பட்டு மின்னஞ்சல் செய்யப்படும்.',
  'Analog fuel sensor (AIN1)': 'அனலாக் எரிபொருள் சென்சார் (AIN1)',
  'Analog voltage (min / max)': 'அனலாக் மின்னழுத்தம் (குறைந்தது / அதிகபட்சம்)',
  'Android 7 or newer is needed.': 'Android 7 அல்லது புதியது தேவை.',
  'Android has put the app in a restricted standby group (limits background work and network)': 'Android ஆப்பைக் கட்டுப்படுத்தப்பட்ட காத்திருப்புக் குழுவில் வைத்துள்ளது (பின்னணி வேலை மற்றும் நெட்வொர்க் வரம்பு)',
  'Android restricts the app in the background': 'Android பின்னணியில் ஆப்பைக் கட்டுப்படுத்துகிறது',
