  'Anyone with the link can watch the live position, speed and status in a browser, without the app, until it expires.': 'இணைப்பு உள்ள எவரும் செயலி இல்லாமல் உலாவியில் நேரலை இருப்பிடம், வேகம், நிலையை அது காலாவதியாகும் வரை பார்க்கலாம்.',
