  'API requests are refused (402 LICENCE_EXPIRED) until the licence is renewed.': 'உரிமம் புதுப்பிக்கப்படும் வரை API கோரிக்கைகள் மறுக்கப்படும் (402 LICENCE_EXPIRED).',
