  'Appearance': 'தோற்றம்',
  'Applies to': 'இதற்குப் பொருந்தும்',
  'Applies to {{name}}. Overspeed alerts fire above this speed. Leave empty for the vehicle-type default ({{n}} km/h).': '{{name}} க்குப் பொருந்தும். இந்த வேகத்தை மீறினால் அதிவேக எச்சரிக்கைகள் வரும். வாகன வகை இயல்புநிலைக்கு ({{n}} km/h) காலியாக விடவும்.',
  'Applies to {{name}}. Overspeed alerts fire above this speed. Leave empty for the vehicle-type default.': '{{name}} க்குப் பொருந்தும். இந்த வேகத்தை மீறினால் அதிவேக எச்சரிக்கைகள் வரும். வாகன வகை இயல்புநிலைக்கு காலியாக விடவும்.',
  'Applies to all vehicles.': 'அனைத்து வாகனங்களுக்கும் பொருந்தும்.',
  'Applies to every vehicle unless a group or vehicle has its own setting.': 'குழு அல்லது வாகனத்துக்கு தனி அமைப்பு இல்லாவிட்டால் ஒவ்வொரு வாகனத்துக்கும் பொருந்தும்.',
  'Applies to selected branches / groups / vehicles (set on the web).': 'தேர்ந்தெடுத்த கிளைகள் / குழுக்கள் / வாகனங்களுக்குப் பொருந்தும் (வெப்பில் அமைக்கவும்).',
  'Apply': 'பயன்படுத்து',
