  'Approve for your company?': 'உங்கள் நிறுவனத்தின் சார்பில் ஒப்புதல் அளிக்கவா?',
  'Approved': 'அங்கீகரிக்கப்பட்டது',
  'Approved {{time}}': 'ஒப்புதல் {{time}}',
  'Approved by the customer': 'வாடிக்கையாளர் ஒப்புதல் அளித்தார்',
  'Approved by the provider': 'வழங்குநர் ஒப்புதல் அளித்தார்',
  'Approved for your company. Waiting for the other company.': 'உங்கள் நிறுவனத்தின் சார்பில் ஒப்புதல் அளிக்கப்பட்டது. மற்ற நிறுவனத்துக்காகக் காத்திருக்கிறது.',
  'Approved; not on a trip yet.': 'அங்கீகரிக்கப்பட்டது; இன்னும் பயணத்தில் இல்லை.',
  'Approved: agreement active': 'ஒப்புதல் அளிக்கப்பட்டது: ஒப்பந்தம் செயலில்',
  'approximate': 'தோராயமாக',
  'Approximate location (within about 11 m).': 'தோராய இடம் (சுமார் 11 மீ க்குள்).',
  'Approximate point': 'தோராயப் புள்ளி',
  'Archive': 'காப்பகப்படுத்து',
  'Archive passenger?': 'பயணியைக் காப்பகப்படுத்தவா?',
  'Archived': 'காப்பகப்படுத்தப்பட்டது',
  'Archived passengers are kept with their history; their login is disabled.': 'காப்பகப்படுத்திய பயணிகள் அவர்களின் வரலாற்றுடன் வைக்கப்படுவர்; அவர்களின் உள்நுழைவு முடக்கப்படும்.',
  'Area only: check the pin': 'பகுதி மட்டும்: பின்னைச் சரிபார்க்கவும்',
  'Arm vehicles at set times (for example overnight). Starting or moving an armed vehicle sounds a loud alarm, also through Do Not Disturb on phones.': 'குறிப்பிட்ட நேரங்களில் வாகனங்களை இயக்கத்தில் வைக்கவும் (எ.கா. இரவு முழுவதும்). இயக்கத்தில் உள்ள வாகனத்தை இயக்கினால் அல்லது நகர்த்தினால், தொலைபேசியில் தொந்தரவு செய்யாதே பயன்முறையிலும் உரத்த அலாரம் ஒலிக்கும்.',
  'Armed during the times below, every week': 'ஒவ்வொரு வாரமும் கீழே உள்ள நேரங்களில் இயக்கத்தில்',
  'Armed now: {{n}}.': 'இப்போது இயக்கத்தில்: {{n}}.',
  'Armed until {{time}}': '{{time}} வரை இயக்கத்தில்',
