  'Choose a vehicle': 'வாகனத்தைத் தேர்ந்தெடுக்கவும்',
  'Choose a vehicle and a period to replay its route, trips, stops and alerts.': 'வழி, பயணங்கள், நிறுத்தங்கள் மற்றும் எச்சரிக்கைகளை மீண்டும் காண வாகனம் மற்றும் காலத்தைத் தேர்ந்தெடுக்கவும்.',
  'Choose a vehicle type': 'வாகன வகையைத் தேர்ந்தெடுக்கவும்',
  'Choose at least one before proposing. Every grant is limited to the sites below.': 'முன்மொழிவதற்கு முன் குறைந்தது ஒன்றைத் தேர்ந்தெடுக்கவும். ஒவ்வொரு அனுமதியும் கீழே உள்ள தளங்களுக்கு மட்டுமே.',
  'Choose at least one day': 'குறைந்தது ஒரு நாளைத் தேர்ந்தெடுக்கவும்',
  'Choose at least one day for each time window': 'ஒவ்வொரு நேர இடைவெளிக்கும் குறைந்தது ஒரு நாளைத் தேர்ந்தெடுக்கவும்',
  'Choose at least one grant before proposing the agreement': 'ஒப்பந்தத்தை முன்மொழிவதற்கு முன் குறைந்தது ஒரு அனுமதியைத் தேர்ந்தெடுக்கவும்',
  'Choose at least one passenger': 'குறைந்தது ஒரு பயணியைத் தேர்ந்தெடுக்கவும்',
  'Choose at least one report': 'குறைந்தது ஒரு அறிக்கையைத் தேர்ந்தெடுக்கவும்',
  'Choose at least one shift.': 'குறைந்தது ஒரு ஷிஃப்ட்டைத் தேர்ந்தெடுக்கவும்.',
  'Choose at least one vehicle.': 'குறைந்தது ஒரு வாகனத்தைத் தேர்ந்தெடுக்கவும்.',
  'Choose at least one work-site geofence': 'குறைந்தது ஒரு பணித்தள ஜியோஃபென்ஸைத் தேர்ந்தெடுக்கவும்',
  'Choose at most {{days}} days': 'அதிகபட்சம் {{days}} நாட்களைத் தேர்ந்தெடுக்கவும்',
  'Choose both dates': 'இரண்டு தேதிகளையும் தேர்ந்தெடுக்கவும்',
