  'Choose columns': 'நெடுவரிசைகளைத் தேர்ந்தெடுக்கவும்',
  'Choose exactly one vehicle (and no branches or groups) for this report': 'இந்த அறிக்கைக்கு சரியாக ஒரு வாகனத்தைத் தேர்ந்தெடுக்கவும் (கிளைகள் அல்லது குழுக்கள் வேண்டாம்)',
  'Choose geofences': 'ஜியோஃபென்ஸ்களைத் தேர்ந்தெடு',
