  'Draw the geofence on the map': 'வரைபடத்தில் ஜியோஃபென்ஸ் வரையவும்',
  'Draw the zone on the map, then set the rules on the right.': 'வரைபடத்தில் மண்டலத்தை வரைந்து, பின் வலதுபுறம் விதிகளை அமைக்கவும்.',
  'Draw them in Geofences first (office, depot, client sites…).': 'முதலில் ஜியோஃபென்ஸில் வரையவும் (அலுவலகம், கிடங்கு, வாடிக்கையாளர் தளம்…).',
  'Draw them in Geofences first and give each one its branch.': 'முதலில் ஜியோஃபென்ஸில் வரைந்து, ஒவ்வொன்றுக்கும் அதன் கிளையைக் கொடுங்கள்.',
  'Draw them in Geofences first and give each store its branch. Staff count only at their own branch, and at sites without a branch.': 'முதலில் ஜியோஃபென்ஸில் இவற்றை வரைந்து ஒவ்வொரு கடைக்கும் அதன் கிளையை அமைக்கவும். பணியாளர்கள் தங்கள் கிளையிலும் கிளை இல்லாத இடங்களிலும் மட்டுமே கணக்கிடப்படுவார்கள்.',
  'Draw with the tools on the map, or place a circle at a vehicle.': 'வரைபடக் கருவிகளால் வரையவும், அல்லது ஒரு வாகனத்தில் வட்டம் வைக்கவும்.',
