  'Driver behaviour events from dashcams (fatigue, phone, smoking, collision warnings, crashes) with cabin snapshots.': 'டேஷ்கேம்களிலிருந்து ஓட்டுநர் நடத்தை நிகழ்வுகள் (சோர்வு, தொலைபேசி, புகைபிடித்தல், மோதல் எச்சரிக்கை, விபத்து) கேபின் ஸ்னாப்ஷாட்களுடன்.',
