  'Drop-down values used across forms. System values are provided by the platform.': 'படிவங்களில் பயன்படுத்தப்படும் கீழிறங்கு மதிப்புகள். கணினி மதிப்புகள் தளத்தால் வழங்கப்படுகின்றன.',
