  'Due by date, by odometer, or whichever comes first. The odometer is the distance recorded by VeeTrax plus the vehicle\'s odometer offset.': 'தேதி, ஓடோமீட்டர் அல்லது எது முதலில் வருகிறதோ அதன்படி. ஓடோமீட்டர் = VeeTrax பதிவு செய்த தூரம் + வாகனத்தின் ஓடோமீட்டர் ஆஃப்செட்.',
