  'e.g. Wi-Fi location 2.5 km off': 'எ.கா. வைஃபை இடம் 2.5 கிமீ தள்ளி',
  'Each device connection is mirrored on its own TCP connection, login first. Replies from this server are ignored.': 'ஒவ்வொரு சாதன இணைப்பும் தனி TCP இணைப்பில் நகலெடுக்கப்படும், முதலில் உள்நுழைவு. இந்த சர்வரின் பதில்கள் புறக்கணிக்கப்படும்.',
  'Each key reads the data of the whole company (or one branch), limited to its scopes. Requests are limited per minute and per day.': 'ஒவ்வொரு விசையும் முழு நிறுவனத்தின் (அல்லது ஒரு கிளையின்) தரவை அதன் அனுமதி வரம்புகளுக்குள் படிக்கும். கோரிக்கைகள் நிமிடத்திற்கும் நாளுக்கும் வரம்பிடப்படும்.',
  'Each person has one VeeTrax login, and an email or mobile number can belong to one login only. This one is already used by a login in another company, by a VeeTrax administrator, or by another passenger or driver. Use a different email or mobile number for this login, or ask the owner of the existing login to change theirs.': 'ஒவ்வொருவருக்கும் ஒரே VeeTrax உள்நுழைவு; ஒரு மின்னஞ்சல் அல்லது கைபேசி எண் ஒரு உள்நுழைவுக்கு மட்டுமே சொந்தமாக இருக்கலாம். இது ஏற்கெனவே வேறு நிறுவனத்தின் உள்நுழைவு, VeeTrax நிர்வாகி, அல்லது வேறு பயணி / ஓட்டுநரால் பயன்படுத்தப்படுகிறது. இந்த உள்நுழைவுக்கு வேறு மின்னஞ்சல் அல்லது கைபேசி எண்ணைப் பயன்படுத்தவும், அல்லது தற்போதைய உள்நுழைவின் உரிமையாளரிடம் அவர்களுடையதை மாற்றச் சொல்லவும்.',
  'Each person, each day: shift, first in, last out, hours, late, early exit, overtime, location, selfie and corrections.': 'ஒவ்வொருவருக்கும், ஒவ்வொரு நாளும்: ஷிப்ட், முதல் வருகை, கடைசி வெளியேற்றம், மணிநேரம், தாமதம், முன்கூட்டியே வெளியேற்றம், கூடுதல் நேரம், இருப்பிடம், செல்ஃபி, திருத்தங்கள்.',
  'Each plan may use every chosen vehicle.': 'ஒவ்வொரு திட்டமும் தேர்ந்தெடுத்த ஒவ்வொரு வாகனத்தையும் பயன்படுத்தலாம்.',
  'Each route with passengers becomes a trip on the dispatch board, with its vehicle and seats. The plan then becomes read-only.': 'பயணிகள் உள்ள ஒவ்வொரு வழித்தடமும் அதன் வாகனம் மற்றும் இருக்கைகளுடன் அனுப்புதல் பலகையில் ஒரு பயணமாகிறது. பின்னர் திட்டம் படிக்க மட்டுமானதாகிறது.',
  'Each tracker needs a yearly licence.': 'ஒவ்வொரு டிராக்கருக்கும் ஆண்டு உரிமம் தேவை.',
