  'Email, SMS, push and WhatsApp wording for every alert and system message. Company versions override the system defaults.': 'ஒவ்வொரு எச்சரிக்கை மற்றும் சிஸ்டம் செய்திக்கான மின்னஞ்சல், SMS, புஷ் மற்றும் WhatsApp வாசகம். நிறுவனப் பதிப்புகள் சிஸ்டம் இயல்புநிலைகளை மாற்றும்.',
