  'Employee transport · door to door': 'ஊழியர் போக்குவரத்து · வீடு முதல் வீடு',
  'Employee transport for your company. More figures appear here as each part of the module is switched on.': 'உங்கள் நிறுவனத்துக்கான ஊழியர் போக்குவரத்து. தொகுதியின் ஒவ்வொரு பகுதியும் இயக்கப்படும்போது இங்கு மேலும் எண்ணிக்கைகள் தோன்றும்.',
  'Employee transport is switched on for {{company}}.': '{{company}} க்கு ஊழியர் போக்குவரத்து இயக்கப்பட்டுள்ளது.',
  'Employee transport profile: who to pick up, where and how.': 'பணியாளர் போக்குவரத்துச் சுயவிவரம்: யாரை, எங்கே, எப்படி அழைத்துச் செல்வது.',
  'Employee transport profiles, home pickup points, offices and shuttle stops, and seats per vehicle.': 'ஊழியர் போக்குவரத்து விவரங்கள், வீட்டு ஏற்றும் இடங்கள், அலுவலகங்கள், ஷட்டில் நிறுத்தங்கள், வாகனத்துக்கான இருக்கைகள்.',
  'Employee transport: corporate admin (agreements, settings, trips)': 'ஊழியர் போக்குவரத்து: நிறுவன நிர்வாகி (ஒப்பந்தங்கள், அமைப்புகள், பயணங்கள்)',
  'Employee transport: dispatcher for assigned branches / sites': 'ஊழியர் போக்குவரத்து: ஒதுக்கப்பட்ட கிளைகள் / தளங்களுக்கான அனுப்புநர்',
  'Employee transport: driver (own assigned trips only)': 'ஊழியர் போக்குவரத்து: ஓட்டுநர் (தனக்கு ஒதுக்கப்பட்ட பயணங்கள் மட்டும்)',
  'Employee transport: passenger (own commute only)': 'ஊழியர் போக்குவரத்து: பயணி (சொந்தப் பயணம் மட்டும்)',
  'Employee\'s answer: {{answer}}': 'ஊழியரின் பதில்: {{answer}}',
  'employee@example.com': 'employee@example.com',
  'Employees and vehicles': 'ஊழியர்களும் வாகனங்களும்',
  'Employees normally give or withdraw consent themselves in the app. Record it here only when the employee has agreed in another way, for example on a signed form.': 'பணியாளர்கள் வழக்கமாகச் செயலியில் தாங்களே ஒப்புதல் அளிப்பர் அல்லது திரும்பப் பெறுவர். கையொப்பமிட்ட படிவம் போன்ற வேறு வழியில் ஒப்புக்கொண்டிருந்தால் மட்டுமே இங்கே பதிவு செய்யவும்.',
  'Employees who use company transport: where to pick them up, consent, and their app login.': 'நிறுவனப் போக்குவரத்தைப் பயன்படுத்தும் பணியாளர்கள்: எங்கே அழைத்துச் செல்வது, ஒப்புதல், அவர்களின் செயலி உள்நுழைவு.',
  'Empty = 10 L or 5 % of the tank, whichever is more ({{n}} L)': 'காலி = 10 லி. அல்லது தொட்டியின் 5 %, எது அதிகமோ அது ({{n}} லி.)',
