  'Enter a valid latitude (−90 to 90) and longitude (−180 to 180), not 0, 0.': 'சரியான அட்சரேகை (−90 முதல் 90) மற்றும் தீர்க்கரேகை (−180 முதல் 180) உள்ளிடவும், 0, 0 அல்ல.',
