  'Events': 'நிகழ்வுகள்',
  'Events appear here when a dashcam reports fatigue, phone use, smoking, collision warnings or a crash.': 'டேஷ்கேம் சோர்வு, தொலைபேசி பயன்பாடு, புகைபிடித்தல், மோதல் எச்சரிக்கை அல்லது விபத்தைப் புகாரளிக்கும்போது நிகழ்வுகள் இங்கே தோன்றும்.',
  'Events appear here when a dashcam with driver monitoring, or a tracker with harsh driving detection, reports them.': 'ஓட்டுநர் கண்காணிப்பு டாஷ்கேம் அல்லது கடுமையான ஓட்டுதலைக் கண்டறியும் டிராக்கர் அனுப்பும்போது நிகழ்வுகள் இங்கே தோன்றும்.',
  'Events per day': 'நாள் வாரியான நிகழ்வுகள்',
  'Every (days)': 'ஒவ்வொரு (நாட்கள்)',
  'Every (km)': 'ஒவ்வொரு (km)',
  'every 5 s': 'ஒவ்வொரு 5 வி',
  'Every AC on / off and door open / closed period with duration, distance and start / end address.': 'ஒவ்வொரு AC இயக்கு / அணை மற்றும் கதவு திறப்பு / மூடல் காலம், நேரம், தூரம் மற்றும் தொடக்க / முடிவு முகவரியுடன்.',
  'Every alert': 'ஒவ்வொரு எச்சரிக்கையும்',
  'Every alert (overspeed, SOS, power cut, geofence, fuel…).': 'ஒவ்வொரு எச்சரிக்கையும் (அதிவேகம், SOS, மின் துண்டிப்பு, ஜியோஃபென்ஸ், எரிபொருள்…).',
  'Every alert raised for vehicles in your scope. Opening an alert marks it read for you; acknowledging marks it handled for everyone.': 'உங்கள் வரம்பிலுள்ள வாகனங்களுக்கான அனைத்து எச்சரிக்கைகள். ஒரு எச்சரிக்கையைத் திறந்தால் அது உங்களுக்கு மட்டும் படித்ததாகும்; ஒப்புக்கொண்டால் அனைவருக்கும் கையாளப்பட்டதாகும்.',
  'Every change is also recorded in the audit log.': 'ஒவ்வொரு மாற்றமும் தணிக்கைப் பதிவிலும் பதிவு செய்யப்படும்.',
  'Every change to settings, recipients and snoozes at this level is listed here.': 'இந்த நிலையில் அமைப்புகள், பெறுநர்கள் மற்றும் ஸ்னூஸ்களில் செய்த ஒவ்வொரு மாற்றமும் இங்கே பட்டியலிடப்படும்.',
  'Every day': 'ஒவ்வொரு நாளும்',
  'Every detected refill and drain (possible fuel theft) with the level before and after.': 'கண்டறியப்பட்ட ஒவ்வொரு நிரப்புதலும் வடிகாலும் (சாத்தியமான எரிபொருள் திருட்டு), முன் மற்றும் பின் அளவுடன்.',
  'Every device on the platform. Assign stock devices to a company.': 'தளத்தில் உள்ள அனைத்து சாதனங்களும். இருப்பு சாதனங்களை ஒரு நிறுவனத்திற்கு ஒதுக்கவும்.',
  'Every ignition change with how long the previous state lasted.': 'ஒவ்வொரு இக்னிஷன் மாற்றமும், முந்தைய நிலை எவ்வளவு நேரம் நீடித்தது என்பதுடன்.',
  'Every new alert is announced through the speaker while the app is open.': 'செயலி திறந்திருக்கும்போது ஒவ்வொரு புதிய எச்சரிக்கையும் ஸ்பீக்கரில் அறிவிக்கப்படும்.',
  'Every passenger has a seat on a route.': 'ஒவ்வொரு பயணிக்கும் ஒரு வழித்தடத்தில் இருக்கை உள்ளது.',
  'Every planned trip with route, vehicle, driver, status, planned and actual start and end, delay, stops done, skipped stops, deviations and distance.': 'ஒவ்வொரு திட்டமிட்ட பயணமும் — வழித்தடம், வாகனம், ஓட்டுநர், நிலை, திட்டமிட்ட மற்றும் உண்மையான தொடக்கம், முடிவு, தாமதம், முடிந்த நிறுத்தங்கள், தவறவிட்ட நிறுத்தங்கள், வழி விலகல்கள் மற்றும் தூரத்துடன்.',
  'Every scheduled day in this range already has a booking or is skipped.': 'இந்த வரம்பில் உள்ள ஒவ்வொரு அட்டவணை நாளுக்கும் ஏற்கனவே முன்பதிவு உள்ளது அல்லது தவிர்க்கப்பட்டது.',
  'Every shift needs a name': 'ஒவ்வொரு ஷிப்டுக்கும் பெயர் தேவை',
  'Every sign-in and change made in this company. Open a row to see what changed.': 'இந்த நிறுவனத்தில் நடந்த ஒவ்வொரு உள்நுழைவும் மாற்றமும். என்ன மாறியது என்பதைப் பார்க்க ஒரு வரிசையைத் திறக்கவும்.',
  'Every time someone left the site during a shift: how long, official or personal, what they said and who decided.': 'ஷிப்ட் நேரத்தில் ஒவ்வொரு முறை பணியிடத்தை விட்டு வெளியேறியபோதும்: எவ்வளவு நேரம், அலுவல் பணியா தனிப்பட்டதா, அவர் சொன்னது, முடிவு செய்தவர்.',
  'Every trip with start/end, duration, distance and speeds.': 'ஒவ்வொரு பயணமும் — தொடக்கம்/முடிவு, கால அளவு, தூரம் மற்றும் வேகங்களுடன்.',
  'Every user with access to the vehicle (push default)': 'வாகனத்தை அணுகக்கூடிய ஒவ்வொரு பயனரும் (புஷ் இயல்புநிலை)',
  'Every vehicle, every second, one screen.': 'ஒவ்வொரு வாகனமும், ஒவ்வொரு நொடியும், ஒரே திரையில்.',
  'Everyone has a seat': 'அனைவருக்கும் இருக்கை உள்ளது',
  'Everyone who can see it': 'இதைப் பார்க்கக்கூடிய அனைவரும்',
