  'first, then come back to this page. Can’t sign in? Call {{phone}} or e-mail {{email}} from your registered address and we will delete it for you.': 'செய்து, பின் இந்தப் பக்கத்துக்குத் திரும்பவும். உள்நுழைய முடியவில்லையா? {{phone}} ஐ அழைக்கவும் அல்லது பதிவுசெய்த முகவரியிலிருந்து {{email}} க்கு மின்னஞ்சல் அனுப்பவும், நாங்கள் நீக்கித் தருவோம்.',
