  'Fix': 'சரிசெய்ய',
  'Fix the highlighted stops before saving.': 'சேமிக்கும் முன் குறிக்கப்பட்ட நிறுத்தங்களைச் சரிசெய்யவும்.',
  'Fix the rows with errors in the file and import it again. Rows already imported stay unchanged, so nothing is created twice.': 'கோப்பில் பிழையுள்ள வரிசைகளைத் திருத்தி மீண்டும் இறக்குமதி செய்யவும். ஏற்கெனவே இறக்குமதியான வரிசைகள் மாறாது, எனவே எதுவும் இருமுறை உருவாகாது.',
