  'Free for 100 days, then a yearly licence. Uses mobile data lightly and saves battery when the phone is still.': '100 நாட்கள் இலவசம், பின் வருடாந்திர உரிமம். குறைவான மொபைல் டேட்டா பயன்படுத்தும்; ஃபோன் அசையாதபோது பேட்டரியைச் சேமிக்கும்.',
  'Free seats move from your pool to the customer; each keeps its own expiry date.': 'இலவச இருக்கைகள் உங்கள் தொகுப்பிலிருந்து வாடிக்கையாளருக்குச் செல்லும்; ஒவ்வொன்றும் தன் காலாவதி தேதியை வைத்திருக்கும்.',
  'Free seats without an invoice (trials, replacements). Recorded in the audit log with the reason.': 'விலைப்பட்டியல் இல்லாத இலவச இருக்கைகள் (சோதனை, மாற்று). காரணத்துடன் தணிக்கைப் பதிவில் சேமிக்கப்படும்.',
