  'Get every alert for the company in addition to the default recipients (users of the vehicle and its branch). Which alerts use email or SMS is set per alert below.': 'இயல்புநிலை பெறுநர்களுடன் (வாகனம் மற்றும் அதன் கிளையின் பயனர்கள்) கூடுதலாக நிறுவனத்தின் அனைத்து எச்சரிக்கைகளையும் பெறுங்கள். எந்த எச்சரிக்கைகள் மின்னஞ்சல் அல்லது SMS பயன்படுத்தும் என்பது கீழே ஒவ்வொரு எச்சரிக்கைக்கும் அமைக்கப்படும்.',
  'Get every alert for this vehicle in addition to the default recipients (users of the vehicle and its branch). Which alerts use email or SMS is set per alert below.': 'இயல்புநிலை பெறுநர்களுடன் (வாகனம் மற்றும் அதன் கிளையின் பயனர்கள்) கூடுதலாக இந்த வாகனத்தின் அனைத்து எச்சரிக்கைகளையும் பெறுங்கள். எந்த எச்சரிக்கைகள் மின்னஞ்சல் அல்லது SMS பயன்படுத்தும் என்பது கீழே ஒவ்வொரு எச்சரிக்கைக்கும் அமைக்கப்படும்.',
