  'If an account exists for that address, we\'ve sent a link to reset your password. It expires in 30 minutes.': 'அந்த முகவரிக்கு கணக்கு இருந்தால், கடவுச்சொல்லை மீட்டமைக்க இணைப்பை அனுப்பியுள்ளோம். அது 30 நிமிடங்களில் காலாவதியாகும்.',
  'If an older VeeTrax app shows "App not installed", uninstall the old one first, then install again.': 'பழைய VeeTrax ஆப் "App not installed" எனக் காட்டினால், முதலில் பழையதை நீக்கி மீண்டும் நிறுவவும்.',
