  'Inactive drivers can\'t be assigned and their card is ignored.': 'செயலற்ற ஓட்டுநர்களை ஒதுக்க முடியாது, அவர்களின் அட்டை புறக்கணிக்கப்படும்.',
  'Inactive geofences raise no alerts': 'செயலற்ற ஜியோஃபென்ஸ்கள் எச்சரிக்கை எழுப்பாது',
  'Inactive objects are hidden from the live map and ignored by the processor.': 'செயலற்ற பொருட்கள் நேரலை வரைபடத்தில் மறைக்கப்படும், செயலாக்கியால் புறக்கணிக்கப்படும்.',
