  'IP address': 'IP முகவரி',
  'is kept with their history but no longer planned, and their app login is disabled. You can restore them later.': 'அவர்களின் வரலாற்றுடன் வைக்கப்படுவார், ஆனால் இனி திட்டமிடப்பட மாட்டார்; அவர்களின் செயலி உள்நுழைவு முடக்கப்படும். பின்னர் மீட்டெடுக்கலாம்.',
