  'It comes back into History, trips, distance and reports.': 'இது வரலாறு, பயணங்கள், தூரம் மற்றும் அறிக்கைகளில் மீண்டும் வரும்.',
  'It may belong to companies you are not part of.': 'இது நீங்கள் சேராத நிறுவனங்களுக்குச் சொந்தமாக இருக்கலாம்.',
  'It may have been deleted or moved, or you may no longer have access. Choose another vehicle.': 'இது நீக்கப்பட்டிருக்கலாம் அல்லது மாற்றப்பட்டிருக்கலாம், அல்லது உங்களுக்கு இனி அணுகல் இல்லாமல் இருக்கலாம். வேறு வாகனத்தைத் தேர்ந்தெடுக்கவும்.',
  'It may have been deleted, or you may not have access to its vehicle.': 'இது நீக்கப்பட்டிருக்கலாம், அல்லது இதன் வாகனத்துக்கான அணுகல் உங்களுக்கு இல்லாமல் இருக்கலாம்.',
  'It may have been removed or you no longer have access.': 'இது நீக்கப்பட்டிருக்கலாம் அல்லது உங்களுக்கு இனி அணுகல் இல்லாமல் இருக்கலாம்.',
  'It tracks a': 'இது கண்காணிப்பது',
  'It will be left out of History, trips, distance and reports. It stays saved with your name and reason, so it can be restored.': 'இது வரலாறு, பயணங்கள், தூரம் மற்றும் அறிக்கைகளில் இருந்து விலக்கப்படும். உங்கள் பெயர் மற்றும் காரணத்துடன் சேமிக்கப்பட்டிருக்கும், எனவே மீட்டெடுக்கலாம்.',
  'Item': 'உருப்படி',
  'Item {{n}}': 'உருப்படி {{n}}',
  'Items forwarded': 'அனுப்பிய உருப்படிகள்',
  'Its devices move with it, each with its paid licence (same expiry). Groups, branch, user access and the current driver of the old company are removed.': 'அதன் சாதனங்களும் உடன் செல்லும், ஒவ்வொன்றும் அதன் கட்டண உரிமத்துடன் (அதே காலாவதி). பழைய நிறுவனத்தின் குழுக்கள், கிளை, பயனர் அணுகல், தற்போதைய ஓட்டுநர் நீக்கப்படும்.',
  'Its service history is kept.': 'அதன் சர்வீஸ் வரலாறு வைக்கப்படும்.',
  'JT/T 808': 'JT/T 808',
  'Jump / outlier': 'தாவல் / விலகிய புள்ளி',
  'Jump to alert {{message}}': 'எச்சரிக்கை {{message}}-க்குச் செல்',
  'Jump to stop at {{time}}': '{{time}} நிறுத்தத்திற்குச் செல்',
  'just now': 'இப்போதுதான்',
  'Keep an email or a mobile number to sign in with.': 'உள்நுழைய ஒரு மின்னஞ்சல் அல்லது மொபைல் எண்ணை வைத்திருக்கவும்.',
  'Keep events for (days)': 'நிகழ்வுகளை வைத்திருக்கும் காலம் (நாட்கள்)',
  'Keep inside': 'உள்ளே வைத்திரு',
  'Keep the licences active (e.g. price correction). Otherwise the credited licences end now.': 'உரிமங்களைச் செயலில் வைத்திரு (எ.கா. விலைத் திருத்தம்). இல்லையெனில் வரவு வைக்கப்பட்ட உரிமங்கள் இப்போதே முடியும்.',
  'Keep the vehicle centred': 'வாகனத்தை மையத்தில் வை',
  'Keep this, discard the others': 'இதை வைத்து, மற்றவற்றை நிராகரி',
  'Keep tracking always on': 'கண்காணிப்பை எப்போதும் இயக்கத்தில் வை',
