  'Keep-in': 'உள்ளே இருக்க',
  'Keeps each route (and so the longest ride) short; 0 to ignore.': 'ஒவ்வொரு வழித்தடத்தையும் (அதனால் மிக நீண்ட பயணத்தையும்) குறுகியதாக வைக்கும்; புறக்கணிக்க 0.',
  'Kept for 30 days. Failed deliveries are retried after 1 min, 5 min, 30 min, 2 h and 6 h.': '30 நாட்கள் வைக்கப்படும். தோல்வியுற்றவை 1 நிமி, 5 நிமி, 30 நிமி, 2 மணி, 6 மணி கழித்து மீண்டும் அனுப்பப்படும்.',
  'Key': 'விசை',
  'Keys let your own software (ERP, dispatch, BI) read VeeTrax data over the REST API.': 'விசைகள் உங்கள் மென்பொருள் (ERP, டிஸ்பாட்ச், BI) REST API வழியாக VeeTrax தரவைப் படிக்க அனுமதிக்கும்.',
  'Kilometres driven since the reading are added automatically.': 'அளவீட்டுக்குப் பின் ஓட்டிய கிலோமீட்டர் தானாகச் சேர்க்கப்படும்.',
  'Kilometres per vehicle by day, week or month, with offline time.': 'ஒவ்வொரு வாகனத்திற்கும் கிலோமீட்டர் — நாள், வாரம் அல்லது மாதம் வாரியாக, ஆஃப்லைன் நேரத்துடன்.',
  'km / L': 'கி.மீ / லி',
