  'Must be https:// and reachable from the internet. Batches of up to 100 positions, at least every 5 seconds, signed with X-VeeTrax-Signature.': 'https:// ஆக இருக்க வேண்டும், இணையத்திலிருந்து அணுகக்கூடியதாக. அதிகபட்சம் 100 இருப்பிடங்கள் கொண்ட தொகுப்புகள், குறைந்தது 5 வினாடிக்கு ஒருமுறை, X-VeeTrax-Signature உடன் கையொப்பமிடப்பட்டது.',
  'Must be https:// and reachable from the internet. Redirects are not followed.': 'https:// ஆக இருக்க வேண்டும், இணையத்திலிருந்து அணுகக்கூடியதாக இருக்க வேண்டும். திசைதிருப்பல்கள் பின்பற்றப்படாது.',
  'Must be on or after the start date': 'தொடக்கத் தேதியன்று அல்லது அதற்குப் பின் இருக்க வேண்டும்',
