  'Mute alerts (e.g. vehicle in the workshop) until a date and time; they resume automatically. Mandatory alerts (SOS) are never snoozed.': 'ஒரு தேதி, நேரம் வரை எச்சரிக்கைகளை முடக்கு (எ.கா. வாகனம் பணிமனையில்); அவை தானாக மீண்டும் தொடங்கும். கட்டாய எச்சரிக்கைகள் (SOS) ஒருபோதும் உறக்கநிலைக்குச் செல்லாது.',
