  'No notifications were sent for this alert (in-app only, or no recipients).': 'இந்த எச்சரிக்கைக்கு அறிவிப்புகள் அனுப்பப்படவில்லை (ஆப்பில் மட்டும், அல்லது பெறுநர்கள் இல்லை).',
