  'No overall result: set the weights above to rank the plans. Each row marks a best value only where better is clear.': 'ஒட்டுமொத்த முடிவு இல்லை: திட்டங்களை வரிசைப்படுத்த மேலே எடைகளை அமைக்கவும். சிறந்தது தெளிவாக இருக்கும் இடத்தில் மட்டுமே ஒவ்வொரு வரிசையும் சிறந்த மதிப்பைக் குறிக்கும்.',
  'No overall result: some plans have no engine numbers for {{what}}.': 'ஒட்டுமொத்த முடிவு இல்லை: சில திட்டங்களில் {{what}} க்கான இயந்திர எண்கள் இல்லை.',
