  'On time on {{n}} of {{due}} working days.': '{{due}} வேலை நாட்களில் {{n}} நாட்கள் நேரத்திற்கு.',
  'On: being at any of your work sites counts as worked, e.g. a day at another branch or a meeting at head office. Off: staff count only at their own branch.': 'இயக்கம்: எந்தப் பணியிடத்தில் இருந்தாலும் வேலையாகக் கணக்கிடப்படும், உதா. வேறு கிளையில் ஒரு நாள் அல்லது தலைமை அலுவலகத்தில் கூட்டம். நிறுத்தம்: ஊழியர்கள் தங்கள் கிளையில் மட்டுமே கணக்கிடப்படுவர்.',
  'Once ON, stays ON until the voltage leaves the range by this much (stops flicker).': 'ஒருமுறை இயக்கமானதும், மின்னழுத்தம் வரம்பிலிருந்து இவ்வளவு விலகும் வரை இயக்கத்திலேயே இருக்கும் (மாற்றம் தவிர்க்கும்).',
  'One company': 'ஒரு நிறுவனம்',
  'One line per person for the period: days present, late, half day and absent, attendance %, hours and overtime.': 'காலத்திற்கு ஒருவருக்கு ஒரு வரி: வந்த, தாமதமான, அரை நாள், வராத நாட்கள், வருகை %, மணிநேரம், கூடுதல் நேரம்.',
  'One line per row.': 'ஒவ்வொரு வரியிலும் ஒன்று.',
  'One line per vehicle for the whole period, with alerts and geofence visits.': 'முழுக் காலத்துக்கும் ஒரு வாகனத்துக்கு ஒரு வரி, எச்சரிக்கைகள் மற்றும் ஜியோஃபென்ஸ் வருகைகளுடன்.',
  'One per company per year (₹, GST inclusive). Requests per minute apply to each API key (a key can only be set lower); requests per day count all keys of the company. Leave vehicles empty for unlimited.': 'ஒரு நிறுவனத்துக்கு ஆண்டுக்கு ஒன்று (₹, GST உட்பட). நிமிடத்துக்கான கோரிக்கைகள் ஒவ்வொரு API விசைக்கும் பொருந்தும் (விசையைக் குறைவாக மட்டுமே அமைக்கலாம்); நாளுக்கான கோரிக்கைகள் நிறுவனத்தின் எல்லா விசைகளையும் சேர்த்துக் கணக்கிடப்படும். வரம்பற்றதற்கு வாகனங்களைக் காலியாக விடவும்.',
  'One plan per shift.': 'ஒவ்வொரு ஷிஃப்ட்டுக்கும் ஒரு திட்டம்.',
  'One protocol': 'ஒரு நெறிமுறை',
  'One vehicle': 'ஒரு வாகனம்',
  'One-off': 'ஒருமுறை',
  'Ongoing': 'நடப்பில்',
  'Online (Razorpay)': 'ஆன்லைன் (Razorpay)',
  'Online now': 'இப்போது ஆன்லைன்',
  'Online vehicles in use today.': 'இன்று பயன்பாட்டில் உள்ள ஆன்லைன் வாகனங்கள்.',
  'Online vehicles that barely moved today (under-used or parked).': 'இன்று அரிதாகவே நகர்ந்த ஆன்லைன் வாகனங்கள் (குறைவான பயன்பாடு அல்லது நிறுத்தப்பட்டவை).',
  'Only a whole-company role with Transport settings edit can change the notices.': 'போக்குவரத்து அமைப்புகளைத் திருத்தும் அனுமதி உள்ள முழு நிறுவனப் பங்கு மட்டுமே அறிவிப்புகளை மாற்ற முடியும்.',
  'Only approved templates can be activated.': 'ஒப்புதல் பெற்ற வார்ப்புருக்களை மட்டுமே செயல்படுத்த முடியும்.',
  'Only bookings that need approval are approved.': 'அங்கீகாரம் தேவைப்படும் முன்பதிவுகள் மட்டுமே அங்கீகரிக்கப்படும்.',
  'Only during…': 'இந்த நேரத்தில் மட்டும்…',
  'Only points you may see are drawn; routes follow the engine’s road geometry.': 'நீங்கள் பார்க்க அனுமதிக்கப்பட்ட புள்ளிகள் மட்டுமே வரையப்படும்; வழித்தடங்கள் இயந்திரத்தின் சாலை வடிவியலைப் பின்பற்றும்.',
  'Only Super Admin can switch companies.': 'சூப்பர் அட்மின் மட்டுமே நிறுவனத்தை மாற்ற முடியும்.',
  'Only the customer company can choose its sites. Empty means all customer sites.': 'வாடிக்கையாளர் நிறுவனம் மட்டுமே தன் தளங்களைத் தேர்ந்தெடுக்க முடியும். காலியாக இருந்தால் எல்லா வாடிக்கையாளர் தளங்களும்.',
  'Only the days of the shift can be chosen.': 'ஷிஃப்டின் நாட்களை மட்டுமே தேர்ந்தெடுக்க முடியும்.',
  'Only the first {{n}} vehicles (by name) are available through the API; requests for other vehicles get 402 API_VEHICLE_LIMIT.': 'API மூலம் முதல் {{n}} வாகனங்கள் (பெயர் வரிசையில்) மட்டுமே கிடைக்கும்; மற்ற வாகனங்களுக்கான கோரிக்கைகளுக்கு 402 API_VEHICLE_LIMIT கிடைக்கும்.',
  'Only this list': 'இந்தப் பட்டியல் மட்டும்',
  'Only vehicles with a wheelchair space will be planned for this passenger.': 'இந்தப் பயணிக்கு சக்கர நாற்காலி இடமுள்ள வாகனங்கள் மட்டுமே திட்டமிடப்படும்.',
  'Only without a seat': 'இருக்கை இல்லாதவை மட்டும்',
