  'Open it and enter that phone’s mobile number: a 6-digit code comes by SMS.': 'அதைத் திறந்து அந்த ஃபோனின் மொபைல் எண்ணை உள்ளிடவும்: SMS மூலம் 6 இலக்கக் குறியீடு வரும்.',
