  'Open the bell to see the latest alerts.': 'சமீபத்திய எச்சரிக்கைகளைப் பார்க்க மணியைத் திறக்கவும்.',
  'Open the dispatch board': 'அனுப்புதல் பலகையைத் திற',
  'Open the downloaded file on the phone. If asked, allow "Install unknown apps" for your browser or file manager.': 'ஃபோனில் பதிவிறக்கிய கோப்பைத் திறக்கவும். கேட்டால் உங்கள் உலாவி அல்லது கோப்பு மேலாளருக்கு "Install unknown apps" அனுமதி அளிக்கவும்.',
