  'Optimise {{n}} plans': '{{n}} திட்டங்களை உகப்பாக்கு',
  'Optimise the day’s bookings into routes, review and adjust them, compare plans and publish one to dispatch.': 'அன்றைய முன்பதிவுகளை வழித்தடங்களாக உகப்பாக்கி, சரிபார்த்துத் திருத்தி, திட்டங்களை ஒப்பிட்டு, ஒன்றை அனுப்புதலுக்கு வெளியிடவும்.',
