  'Passenger restored': 'பயணி மீட்டெடுக்கப்பட்டார்',
  'Passenger seats per vehicle (driver not counted). Route planning never puts more passengers in a vehicle than this.': 'ஒவ்வொரு வாகனத்திலும் பயணி இருக்கைகள் (ஓட்டுநர் சேர்க்கப்படவில்லை). வழித் திட்டமிடல் இதைவிட அதிகப் பயணிகளை ஒரு வாகனத்தில் ஒருபோதும் வைக்காது.',
