  'Pay offline': 'ஆஃப்லைனில் செலுத்து',
  'Pay our representative or at our office. Tell us if you have already paid, or where and when we should collect it.': 'எங்கள் பிரதிநிதியிடம் அல்லது எங்கள் அலுவலகத்தில் செலுத்தவும். ஏற்கனவே செலுத்தியிருந்தால் அல்லது எங்கே, எப்போது வசூலிக்க வேண்டும் என்று தெரிவிக்கவும்.',
  'Pay with UPI app': 'UPI செயலி மூலம் செலுத்து',
  'Payment': 'கட்டணம்',
  'Payment confirmed. Licences activated and invoice emailed.': 'கட்டணம் உறுதிப்படுத்தப்பட்டது. உரிமங்கள் செயல்படுத்தப்பட்டு விலைப்பட்டியல் அனுப்பப்பட்டது.',
  'Payment details (printed on invoices and shown for offline payment)': 'கட்டண விவரங்கள் (விலைப்பட்டியலில் அச்சிடப்பட்டு ஆஃப்லைன் கட்டணத்திற்குக் காட்டப்படும்)',
  'Payment mode': 'கட்டண முறை',
  'Payment not received': 'கட்டணம் பெறப்படவில்லை',
  'Payment received. Licences activate as soon as the bank confirms it.': 'கட்டணம் பெறப்பட்டது. வங்கி உறுதிப்படுத்தியவுடன் உரிமங்கள் செயல்படும்.',
  'Payment received. Your licences are active and the invoice has been e-mailed.': 'கட்டணம் பெறப்பட்டது. உங்கள் உரிமங்கள் செயலில் உள்ளன, விலைப்பட்டியல் மின்னஞ்சல் செய்யப்பட்டது.',
  'Payment recorded. Licences activated and invoice issued.': 'கட்டணம் பதிவானது. உரிமங்கள் செயல்படுத்தப்பட்டு விலைப்பட்டியல் வழங்கப்பட்டது.',
  'Payments to confirm': 'உறுதிப்படுத்த வேண்டிய கட்டணங்கள்',
  'PDF': 'PDF',
  'PDF saved to your downloads': 'PDF பதிவிறக்கங்களில் சேமிக்கப்பட்டது',
  'Peak at': 'உச்சம்',
  'Pending': 'நிலுவையில்',
  'Pending (unacknowledged)': 'நிலுவையில் (உறுதிப்படுத்தப்படாதவை)',
  'Pending changes': 'நிலுவை மாற்றங்கள்',
  'Pending only': 'நிலுவையில் உள்ளவை மட்டும்',
  'People of the other company are shown by their side only.': 'மற்ற நிறுவனத்தின் நபர்கள் அவர்களின் தரப்பால் மட்டுமே காட்டப்படுவார்கள்.',
  'People on this shift': 'இந்த ஷிப்டில் உள்ளவர்கள்',
  'People tracked by phone or ID card appear here.': 'தொலைபேசி அல்லது ID அட்டையால் கண்காணிக்கப்படுபவர்கள் இங்கே தோன்றுவர்.',
  'People who can sign in, their roles and what they can see.': 'உள்நுழையக்கூடிய நபர்கள், அவர்களின் பங்குகள் மற்றும் அவர்கள் பார்க்கக்கூடியவை.',
  'Per channel: use the default lists, add to them, replace them, or notify nobody.': 'ஒவ்வொரு சேனலுக்கும்: இயல்புநிலைப் பட்டியல்களைப் பயன்படுத்து, சேர், மாற்று அல்லது யாருக்கும் அறிவிக்காதே.',
  'Per driver': 'ஓட்டுநர் வாரியாக',
  'Per driver: vehicles driven, trips, distance, driving time and overspeeding (from card swipes and assignments).': 'ஒவ்வொரு ஓட்டுநருக்கும்: ஓட்டிய வாகனங்கள், பயணங்கள், தூரம், ஓட்டும் நேரம், அதிவேகம் (கார்டு ஸ்வைப் மற்றும் ஒதுக்கீடுகளிலிருந்து).',
  'Per driver: vehicles driven, trips, distance, driving time and overspeeding.': 'ஒவ்வொரு ஓட்டுநருக்கும்: ஓட்டிய வாகனங்கள், பயணங்கள், தூரம், ஓட்டும் நேரம், அதிவேகம்.',
  'Per route': 'வழித்தட வாரியாக',
  'Per vehicle': 'வாகன வாரியாக',
  'Per vehicle per day: hours with AC on, AC on with the engine off, door openings and open time.': 'ஒரு வாகனத்திற்கு ஒரு நாளுக்கு: AC இயக்க மணிநேரம், எஞ்சின் அணைந்து AC இயக்கம், கதவு திறப்புகள் மற்றும் திறந்த நேரம்.',
  'Per vehicle per day: start and end level, refills, drains, consumption and km/L (vehicles with a fuel sensor).': 'ஒவ்வொரு வாகனத்திற்கும் ஒவ்வொரு நாளும்: தொடக்க மற்றும் இறுதி அளவு, நிரப்புதல், வடிகால், நுகர்வு மற்றும் கி.மீ/லி. (எரிபொருள் சென்சார் உள்ள வாகனங்கள்).',
  'Per vehicle: fill-ups, litres and fuel cost entered in Fuel & expenses against the GPS distance driven, giving km per litre and cost per km. No fuel sensor needed.': 'ஒவ்வொரு வாகனமும்: எரிபொருள் & செலவுகளில் பதிவு செய்த நிரப்புதல்கள், லிட்டர், எரிபொருள் செலவு — GPS தூரத்துடன் ஒப்பிட்டு கி.மீ/லிட்டர் மற்றும் கி.மீ செலவு. எரிபொருள் சென்சார் தேவையில்லை.',
  'Period': 'காலம்',
  'Period: {{from}} to {{to}}': 'காலம்: {{from}} முதல் {{to}} வரை',
  'Periodic maintenance by date and / or odometer. Mark a service done to log it and roll the reminder forward.': 'தேதி மற்றும் / அல்லது ஓடோமீட்டர் அடிப்படையில் காலமுறை பராமரிப்பு. சர்வீஸைப் பதிவு செய்து நினைவூட்டலை முன்னோக்கி நகர்த்த, அதை முடிந்ததாகக் குறிக்கவும்.',
