  'Processed entries stay in the stream until the cap trims the oldest; only unprocessed ones matter.': 'செயலாக்கப்பட்ட பதிவுகள் வரம்பு பழையவற்றை நீக்கும் வரை ஸ்ட்ரீமில் இருக்கும்; செயலாக்கப்படாதவை மட்டுமே முக்கியம்.',
