  'Publish': 'வெளியிடு',
  'Publish this plan?': 'இந்தத் திட்டத்தை வெளியிடவா?',
  'Publish with {{n}} warning(s) (late arrivals, seats or ride time).': '{{n}} எச்சரிக்கை(கள்) உடன் வெளியிடு (தாமத வருகை, இருக்கைகள் அல்லது பயண நேரம்).',
  // Owner decision 5 (publishing): hard violations, acknowledged warnings, authorised override.
  'These must be fixed before publishing. Edit the routes (move or reorder stops) or re-optimise the plan.': 'வெளியிடும் முன் இவற்றைச் சரிசெய்ய வேண்டும். வழிகளைத் திருத்தவும் (நிறுத்தங்களை நகர்த்தவும் அல்லது வரிசை மாற்றவும்) அல்லது திட்டத்தை மீண்டும் உகப்பாக்கவும்.',
  'I have checked these {{n}} warning(s) and want to publish.': 'இந்த {{n}} எச்சரிக்கை(களை) சரிபார்த்தேன், வெளியிட விரும்புகிறேன்.',
  'Override the arrival-window violations (authorised)': 'வருகை நேர வரம்பு மீறல்களை மேலெழுது (அங்கீகரிக்கப்பட்டது)',
  'Reason for the override (recorded in the audit log)': 'மேலெழுதலுக்கான காரணம் (தணிக்கைப் பதிவில் பதியப்படும்)',
  'At least {{n}} characters, in words.': 'குறைந்தது {{n}} எழுத்துகள், சொற்களில்.',
  'Published with an authorised override': 'அங்கீகரிக்கப்பட்ட மேலெழுதலுடன் வெளியிடப்பட்டது',
  '{{n}} arrival-window violation(s) overridden.': '{{n}} வருகை நேர வரம்பு மீறல்(கள்) மேலெழுதப்பட்டன.',
  'Hard violations (block publishing)': 'கடுமையான மீறல்கள் (வெளியீட்டைத் தடுக்கும்)',
  'arrives {{eta}}, window {{from}}–{{to}}': '{{eta}} மணிக்கு வருகிறது, நேர வரம்பு {{from}}–{{to}}',
  'This plan has violations that block publishing. Edit the routes or re-optimise the plan.': 'இந்தத் திட்டத்தில் வெளியீட்டைத் தடுக்கும் மீறல்கள் உள்ளன. வழிகளைத் திருத்தவும் அல்லது திட்டத்தை மீண்டும் உகப்பாக்கவும்.',
  'The plan’s warnings changed. Check them again and confirm before publishing.': 'திட்டத்தின் எச்சரிக்கைகள் மாறிவிட்டன. வெளியிடும் முன் மீண்டும் சரிபார்த்து உறுதிசெய்யவும்.',
  'Only a whole-company transport administrator may override the publish checks.': 'முழு நிறுவன போக்குவரத்து நிர்வாகி மட்டுமே வெளியீட்டுச் சரிபார்ப்புகளை மேலெழுத முடியும்.',
  'Give a clear reason for the override.': 'மேலெழுதலுக்கான தெளிவான காரணத்தைக் கொடுக்கவும்.',
