  'Rounded to about 11 m. Only the corporate admin sees and changes the exact point.': 'சுமார் 11 மீ க்கு முழுமையாக்கப்பட்டது. துல்லியமான புள்ளியை நிறுவன நிர்வாகி மட்டுமே பார்த்து மாற்றலாம்.',
  'Route': 'வழித்தடம்',
  'Route {{n}} · {{vehicle}}': 'வழித்தடம் {{n}} · {{vehicle}}',
  'Route {{n}} locked: re-optimising keeps its stops and order.': 'வழித்தடம் {{n}} பூட்டப்பட்டது: மீண்டும் உகப்பாக்கும்போது அதன் நிறுத்தங்களும் வரிசையும் மாறாது.',
  'Route {{n}} now uses {{vehicle}}.': 'வழித்தடம் {{n}} இப்போது {{vehicle}} ஐப் பயன்படுத்துகிறது.',
