  'Route {{r}}, stop {{n}}: {{name}}': 'வழித்தடம் {{r}}, நிறுத்தம் {{n}}: {{name}}',
  'Route created. You can add schedules now.': 'வழித்தடம் உருவாக்கப்பட்டது. இப்போது அட்டவணைகளைச் சேர்க்கலாம்.',
  'Route deviation': 'வழித்தட விலகல்',
  'Route map editor': 'வழித்தட வரைபடத் திருத்தி',
  'Route planning': 'வழித்தடத் திட்டமிடல்',
  'Route planning is off': 'வழித்தடத் திட்டமிடல் முடக்கத்தில் உள்ளது',
  'Route planning is switched off for this company.': 'இந்த நிறுவனத்திற்கு வழித்தடத் திட்டமிடல் அணைக்கப்பட்டுள்ளது.',
  'Route planning is switched off for this company. Trips are planned on the dispatch board.': 'இந்த நிறுவனத்திற்கு வழித்தடத் திட்டமிடல் அணைக்கப்பட்டுள்ளது. பயணங்கள் அனுப்புதல் பலகையில் திட்டமிடப்படுகின்றன.',
  'Route planning off': 'வழித்தடத் திட்டமிடல் முடக்கம்',
  'Routes': 'வழித்தடங்கள்',
  'Routes & trips': 'வழித்தடங்கள் & பயணங்கள்',
  'Routes that cannot be published': 'வெளியிட முடியாத வழித்தடங்கள்',
  'Routing consent': 'வழித்தட ஒப்புதல்',
  'Routing is unavailable: no ETAs. Candidates are ranked by free seats and straight-line distance only. Manual assignment still works.': 'வழித்தடம் கிடைக்கவில்லை: வருகை நேரங்கள் இல்லை. பரிந்துரைகள் காலி இருக்கைகள், நேர்கோட்டுத் தூரம் மட்டுமே கொண்டு வரிசைப்படுத்தப்பட்டுள்ளன. கைமுறை ஒதுக்கீடு இன்னும் செயல்படும்.',
  'Routing offline': 'வழித்தடம் இணைப்பில் இல்லை',
  'Routing OK': 'வழித்தடம் சரி',
  'Routing OK · queue paused': 'வழித்தடம் சரி · வரிசை நிறுத்தத்தில்',
  'Routing picks this passenger up at home.': 'வழித்தடம் இந்தப் பயணியை வீட்டிலிருந்து அழைத்துச் செல்லும்.',
  'Routing picks this passenger up at the stop {{name}}.': 'வழித்தடம் இந்தப் பயணியை {{name}} நிறுத்தத்தில் அழைத்துச் செல்லும்.',
  'Routing unavailable': 'வழித்தடம் கிடைக்கவில்லை',
  'Routing unavailable: no ETA': 'வழித்தடம் கிடைக்கவில்லை: வருகை நேரம் இல்லை',
  'Routing unavailable: the changed routes could not be re-timed, so they show no times. Nothing was estimated.': 'வழித்தடம் கிடைக்கவில்லை: மாற்றிய வழித்தடங்களுக்கு மீண்டும் நேரம் கணக்கிட முடியவில்லை, எனவே நேரங்கள் காட்டப்படவில்லை. எதுவும் மதிப்பிடப்படவில்லை.',
  'Routing unavailable: the road engine is not answering.': 'வழித்தடம் கிடைக்கவில்லை: சாலை இயந்திரம் பதிலளிக்கவில்லை.',
  'Routing unavailable: the road engine is not answering. No new times can be produced; dispatch manually from the board meanwhile.': 'வழித்தடம் கிடைக்கவில்லை: சாலை இயந்திரம் பதிலளிக்கவில்லை. புதிய நேரங்களை உருவாக்க முடியாது; அதுவரை பலகையிலிருந்து கைமுறையாக அனுப்பவும்.',
  'Routing unavailable: the road engine is not answering. No times were produced; dispatch manually from the board meanwhile.': 'வழித்தடம் கிடைக்கவில்லை: சாலை இயந்திரம் பதிலளிக்கவில்லை. நேரங்கள் உருவாக்கப்படவில்லை; அதுவரை பலகையிலிருந்து கைமுறையாக அனுப்பவும்.',
  'Routing unavailable: the road engine is switched off.': 'வழித்தடம் கிடைக்கவில்லை: சாலை இயந்திரம் அணைக்கப்பட்டுள்ளது.',
  'Routing unavailable: the road engine took too long.': 'வழித்தடம் கிடைக்கவில்லை: சாலை இயந்திரம் அதிக நேரம் எடுத்தது.',
  'Routing unavailable: the road map is being rebuilt. Try again later.': 'வழித்தடம் கிடைக்கவில்லை: சாலை வரைபடம் மீண்டும் உருவாக்கப்படுகிறது. பின்னர் முயலவும்.',
  'Routing unavailable: this engine is not supported.': 'வழித்தடம் கிடைக்கவில்லை: இந்த இயந்திரம் ஆதரிக்கப்படவில்லை.',
  'Routing uses no location of this passenger until they consent to transport planning.': 'இந்தப் பயணி போக்குவரத்துத் திட்டமிடலுக்கு ஒப்புதல் அளிக்கும் வரை, வழித்தடம் அவரின் எந்த இடத்தையும் பயன்படுத்தாது.',
  'Row': 'வரிசை',
  'Row {{row}}': 'வரிசை {{row}}',
  'Row numbers or ranges, e.g. 1,3-5. Empty = every valid row.': 'வரிசை எண்கள் அல்லது வரம்புகள், எ.கா. 1,3-5. காலி = எல்லா சரியான வரிசைகளும்.',
