  'Send a copy of the data received from devices to another server: a state AIS-140 backend, another tracking platform or a partner.': 'சாதனங்களிலிருந்து பெறும் தரவின் நகலை வேறு சர்வருக்கு அனுப்பவும்: மாநில AIS-140 சர்வர், வேறு கண்காணிப்புத் தளம் அல்லது கூட்டாளர்.',
  'Send a copy of the data received from devices to another server.': 'சாதனங்களிலிருந்து பெறும் தரவின் நகலை வேறு சர்வருக்கு அனுப்பவும்.',
