  'Sends “{{name}}” with sample data, marked [TEST].': '“{{name}}” ஐ மாதிரி தரவுடன் [TEST] எனக் குறித்து அனுப்பும்.',
  'Sends a raw protocol command (support staff).': 'நேரடி புரோட்டோகால் கட்டளையை அனுப்பும் (ஆதரவு ஊழியர்கள்).',
