  'Sensor source, tank capacity, calibration and refill / theft thresholds.': 'சென்சார் மூலம், தொட்டி கொள்ளளவு, அளவுத்திருத்தம் மற்றும் நிரப்புதல் / திருட்டு வரம்புகள்.',
  'sensor value': 'சென்சார் மதிப்பு',
  'Sensor value → litres. Leave empty if the sensor already reports litres.': 'சென்சார் மதிப்பு → லிட்டர். சென்சார் ஏற்கனவே லிட்டரில் தெரிவித்தால் காலியாக விடவும்.',
  'Sensor voltage (mV) → litres, measured while filling the tank. At least 2 rows; values in between are interpolated.': 'சென்சார் மின்னழுத்தம் (mV) → லிட்டர், தொட்டியை நிரப்பும்போது அளவிடப்பட்டது. குறைந்தது 2 வரிசைகள்; இடையிலான மதிப்புகள் இடைக்கணிக்கப்படும்.',
