  'Set a new password': 'புதிய கடவுச்சொல்லை அமை',
  'Set a password for email sign-in': 'மின்னஞ்சல் உள்நுழைவுக்கு கடவுச்சொல்லை அமை',
  'Set a shuttle stop to pick the passenger up there instead of at home.': 'பயணியை வீட்டுக்குப் பதில் அங்கே அழைத்துச் செல்ல ஒரு ஷட்டில் நிறுத்தத்தை அமைக்கவும்.',
  'Set all four weights (0 ignores one; at least one of distance, driving or route length above 0). Nothing is assumed.': 'நான்கு எடைகளையும் அமைக்கவும் (0 அதைப் புறக்கணிக்கும்; தூரம், ஓட்டுதல் அல்லது வழித்தட நீளத்தில் குறைந்தது ஒன்று 0 க்கு மேல்). எதுவும் ஊகிக்கப்படாது.',
  'Set all four weights (at least one of distance, driving or route length above 0).': 'நான்கு எடைகளையும் அமைக்கவும் (தூரம், ஓட்டுதல் அல்லது வழித்தட நீளத்தில் குறைந்தது ஒன்று 0 க்கு மேல்).',
  'Set an interval in km, in days, or both': 'km, நாட்கள் அல்லது இரண்டிலும் இடைவெளியை அமைக்கவும்',
  'Set by Super Admin': 'சூப்பர் அட்மின் அமைப்பது',
  'Set every objective weight (at least one above 0).': 'ஒவ்வொரு நோக்க எடையையும் அமைக்கவும் (குறைந்தது ஒன்று 0 க்கு மேல்).',
  'Set every weight from {{min}} (ignore) to {{max}} (most important). Nothing is assumed.': 'ஒவ்வொரு எடையையும் {{min}} (புறக்கணி) முதல் {{max}} (மிக முக்கியம்) வரை அமைக்கவும். எதுவும் ஊகிக்கப்படாது.',
  'Set here': 'இங்கே அமைக்கப்பட்டது',
  'Set schedule for {{n}} selected': 'தேர்ந்தெடுத்த {{n}}-க்கு அட்டவணை அமை',
  'Set the approval status to Approved before activating this {{channel}} template.': 'இந்த {{channel}} வார்ப்புருவை செயல்படுத்தும் முன் ஒப்புதல் நிலையை Approved என அமைக்கவும்.',
  'Set the location: move the map and tap "Use map centre"': 'இருப்பிடத்தை அமைக்கவும்: வரைபடத்தை நகர்த்தி "வரைபட மையத்தைப் பயன்படுத்து" என்பதைத் தட்டவும்',
  'Set the reading shown for this vehicle, for example 0 after a reset or the reading on its dashboard. Distance keeps adding from that value.': 'இந்த வாகனத்தின் அளவீட்டை அமைக்கவும், எ.கா. மீட்டமைத்த பின் 0 அல்லது டாஷ்போர்டு அளவீடு. தூரம் அந்த மதிப்பிலிருந்து தொடர்ந்து கூடும்.',
  'Set the vehicle\'s passenger seats first (Vehicle seats).': 'முதலில் வாகனத்தின் பயணி இருக்கைகளை அமைக்கவும் (வாகன இருக்கைகள்).',
  'Set up your passengers and vehicles': 'உங்கள் பயணிகளையும் வாகனங்களையும் அமைக்கவும்',
  'Settings': 'அமைப்புகள்',
  'Settings → Apps → VeeTrax Tracker → Battery → No restrictions / Unrestricted': 'அமைப்புகள் → ஆப்ஸ் → VeeTrax Tracker → பேட்டரி → கட்டுப்பாடுகள் இல்லை',
  'Settings → Apps → VeeTrax Tracker → Battery saver → No restrictions': 'அமைப்புகள் → ஆப்ஸ் → VeeTrax Tracker → பேட்டரி சேவர் → கட்டுப்பாடுகள் இல்லை',
  'Settings → Apps → VeeTrax Tracker → Notifications → On': 'அமைப்புகள் → ஆப்ஸ் → VeeTrax Tracker → அறிவிப்புகள் → இயக்கு',
  'Settings → Apps → VeeTrax Tracker → Permissions → Location → Allow all the time': 'அமைப்புகள் → ஆப்ஸ் → VeeTrax Tracker → அனுமதிகள் → இருப்பிடம் → எப்போதும் அனுமதி',
  'Settings → Network → Data Saver → allow unrestricted data for VeeTrax Tracker (or turn Data Saver off)': 'அமைப்புகள் → நெட்வொர்க் → டேட்டா சேவர் → VeeTrax Tracker க்கு வரம்பற்ற டேட்டா அனுமதி (அல்லது டேட்டா சேவரை அணைக்கவும்)',
  'Settings level': 'அமைப்பு நிலை',
