  'Shifts, recurring and one-off bookings, cut-off times and the daily trip list with passengers.': 'ஷிஃப்டுகள், தொடர் மற்றும் ஒருமுறை முன்பதிவுகள், கட்-ஆஃப் நேரங்கள், பயணிகளுடன் தினசரி பயணப் பட்டியல்.',
