  'Short trips out that come back, up to this total a day, are not questioned and count as worked.': 'திரும்பி வரும் சிறிய வெளியேற்றங்கள், நாளுக்கு இந்த மொத்த நேரம் வரை, கேள்வி இல்லை; வேலையாகக் கணக்கிடப்படும்.',
  'Short trips out up to this total are not questioned. 0 = off': 'இந்த மொத்த நேரம் வரை சிறிய வெளியேற்றங்களுக்குக் கேள்வி இல்லை. 0 = நிறுத்தம்',
  'Shorter exits count as inside, with no alert': 'இதைவிடக் குறைவானவை உள்ளே என கணக்கிடப்படும், எச்சரிக்கை இல்லை',
