  'Show trips, stops and alerts': 'பயணங்கள், நிறுத்தங்கள், எச்சரிக்கைகளைக் காட்டு',
  'Showing {{from}}–{{to}} of {{total}}': '{{total}} இல் {{from}}–{{to}} காட்டப்படுகிறது',
  'Showing {{shown}} of {{total}} rows': '{{total}} வரிசைகளில் {{shown}} காட்டப்படுகிறது',
  'Showing the first {{n}} rows of this view. Use the filters to see the others.': 'இந்தக் காட்சியின் முதல் {{n}} வரிசைகள் காட்டப்படுகின்றன. மற்றவற்றைப் பார்க்க வடிகட்டிகளைப் பயன்படுத்தவும்.',
  'Showing the first {{shown}} of {{total}} trips. Narrow the filters to see the rest.': '{{total}} பயணங்களில் முதல் {{shown}} காட்டப்படுகின்றன. மீதியைப் பார்க்க வடிகட்டிகளைக் குறைக்கவும்.',
  'Showing the first {{shown}} rows of {{total}}; totals cover every row. Download the report or narrow the selection for the rest.': '{{total}} இல் முதல் {{shown}} வரிசைகள் காட்டப்படுகின்றன; மொத்தங்கள் எல்லா வரிசைகளையும் உள்ளடக்கும். மீதமுள்ளவற்றுக்கு அறிக்கையைப் பதிவிறக்கவும் அல்லது தேர்வைக் குறைக்கவும்.',
  'Showing the first {{shown}} rows; totals cover every row. Download the report or narrow the selection for the rest.': 'முதல் {{shown}} வரிசைகள் காட்டப்படுகின்றன; மொத்தங்கள் எல்லா வரிசைகளையும் உள்ளடக்கும். மீதமுள்ளவற்றுக்கு அறிக்கையைப் பதிவிறக்கவும் அல்லது தேர்வைக் குறைக்கவும்.',
  'Shown for periods up to 2 months. Choose a shorter period to see each day.': '2 மாதங்கள் வரையிலான காலத்திற்கு மட்டும் காட்டப்படும். ஒவ்வொரு நாளையும் பார்க்க குறுகிய காலத்தைத் தேர்ந்தெடுக்கவும்.',
  'Shows every recorded point in History, labelled good, parked drift, spike, jump, inaccurate or fake GPS, with the cleaned track. For all users who can see History.': 'வரலாற்றில் பதிவான ஒவ்வொரு புள்ளியையும் சரி, நிறுத்தத்தில் நகர்வு, திடீர் விலகல், தாவல், துல்லியமற்றது அல்லது போலி GPS எனக் குறித்து, சுத்தமான பாதையுடன் காட்டும். வரலாற்றைப் பார்க்கக்கூடிய அனைத்துப் பயனர்களுக்கும்.',
