  'Solving': 'தீர்க்கிறது',
  'Some points are outside the routing area.': 'சில புள்ளிகள் வழித்தடப் பகுதிக்கு வெளியே உள்ளன.',
  'Some routes have times that did not come from the routing engine. They are hidden; re-optimise when routing is back.': 'சில வழித்தடங்களின் நேரங்கள் வழித்தட இயந்திரத்திலிருந்து வரவில்லை. அவை மறைக்கப்பட்டுள்ளன; வழித்தடம் திரும்பியதும் மீண்டும் உகப்பாக்கவும்.',
  'Someone changed this meanwhile. The latest data was loaded; check it and try again.': 'இதற்கிடையில் யாரோ இதை மாற்றினர். சமீபத்திய தரவு ஏற்றப்பட்டது; சரிபார்த்து மீண்டும் முயலவும்.',
  'Someone changed this plan meanwhile. The latest version (v{{v}}) is shown; check it and redo your change.': 'இதற்கிடையில் யாரோ இந்தத் திட்டத்தை மாற்றினர். சமீபத்திய பதிப்பு (v{{v}}) காட்டப்படுகிறது; சரிபார்த்து உங்கள் மாற்றத்தை மீண்டும் செய்யவும்.',
  'Someone changed this plan meanwhile. The latest version was loaded; check it and try again.': 'இதற்கிடையில் யாரோ இந்தத் திட்டத்தை மாற்றினர். சமீபத்திய பதிப்பு ஏற்றப்பட்டது; சரிபார்த்து மீண்டும் முயலவும்.',
  'Someone must acknowledge these alerts; others are done once opened. Default: on for SOS, crash, power cut, device offline and every critical alert.': 'இந்த எச்சரிக்கைகளை யாராவது ஒப்புக்கொள்ள வேண்டும்; மற்றவை திறந்தவுடன் முடிந்துவிடும். இயல்பு: SOS, விபத்து, மின் துண்டிப்பு, சாதனம் ஆஃப்லைன் மற்றும் ஒவ்வொரு அவசர எச்சரிக்கைக்கும் இயக்கத்தில்.',
  'Something went wrong': 'ஏதோ தவறு நடந்தது',
  'Sort order': 'வரிசை முறை',
  'SOS / Emergency': 'SOS / அவசரம்',
  'SOS / panic': 'SOS / அவசர உதவி',
  'SOS alarm': 'SOS அலாரம்',
  'SOS and crash alerts play a loud siren and open a full-screen alarm until someone acknowledges them.': 'SOS மற்றும் விபத்து எச்சரிக்கைகள் உரத்த சைரனை ஒலிக்கச் செய்து, யாராவது ஏற்கும் வரை முழுத் திரை அலாரத்தைத் திறக்கும்.',
  'SOS location': 'SOS இருப்பிடம்',
  'SOS, crash and power cut alerts play a loud siren and open a full-screen alarm until someone acknowledges them.': 'SOS, விபத்து மற்றும் மின்வெட்டு எச்சரிக்கைகள் உரத்த சைரனை ஒலிக்கச் செய்து, யாராவது ஏற்கும் வரை முழுத்திரை அலாரத்தைக் காட்டும்.',
  'SOS, crash, power cut and tamper alerts play a loud siren and open a full-screen alarm until someone acknowledges them.': 'SOS, விபத்து, மின்வெட்டு மற்றும் சேதப்படுத்தல் எச்சரிக்கைகள் உரத்த சைரனை ஒலிக்கச் செய்து, யாராவது ஏற்கும் வரை முழுத்திரை அலாரத்தைக் காட்டும்.',
  'Sound off — click to turn on': 'ஒலி அணைப்பில் — இயக்க கிளிக் செய்யவும்',
  'Sound on for Warning and Critical — click to mute': 'எச்சரிக்கை நிலை மற்றும் அவசரத்துக்கு ஒலி இயக்கத்தில் — முடக்க கிளிக் செய்யவும்',
  'Source': 'மூலம்',
  'Speak your question': 'உங்கள் கேள்வியைப் பேசுங்கள்',
  'Speed': 'வேகம்',
