  'Speed limit not saved: {{error}}': 'வேக வரம்பு சேமிக்கப்படவில்லை: {{error}}',
  'Speeding episodes above each vehicle\'s limit with peak speed and duration.': 'ஒவ்வொரு வாகனத்தின் வரம்புக்கு மேலான அதிவேக நிகழ்வுகள், உச்ச வேகம் மற்றும் கால அளவுடன்.',
  'Spike (out and back)': 'திடீர் விலகல் (போய்த் திரும்பல்)',
  'Staff': 'பணியாளர்',
  'Staff (optional)': 'பணியாளர் (விருப்பம்)',
  'Staff absent': 'பணியாளர் வருகை இல்லை',
  'Staff are asked for a selfie in the Tracker app when they reach their work site. It is kept for 90 days. A missing selfie is flagged and does not change the status. Needs Tracker 1.3.5 or later.': 'பணியிடத்தை அடையும்போது Tracker செயலியில் செல்ஃபி கேட்கப்படும். இது 90 நாட்கள் வைக்கப்படும். செல்ஃபி இல்லையெனில் குறிக்கப்படும், நிலை மாறாது. Tracker 1.3.5 அல்லது அதற்குப் பிந்தையது தேவை.',
  'Staff attendance': 'பணியாளர் வருகை',
  'Staff check in and out automatically when they enter and leave a work site.': 'பணித்தளத்தில் நுழையும்போதும் வெளியேறும்போதும் தானாகவே வருகை/வெளியேற்றம் பதிவாகும்.',
  'Staff ID': 'ஊழியர் ID',
  'Staff left work site': 'பணியாளர் பணியிடத்தை விட்டு வெளியேறினார்',
