  'Tolerance': 'சகிப்பு வரம்பு',
  'Toll': 'சுங்கச்சாவடி',
  'Too many attempts. Please wait and try again.': 'அதிக முயற்சிகள். சற்று காத்திருந்து மீண்டும் முயலவும்.',
  'Too many requests. Wait a moment and try again.': 'அதிகமான கோரிக்கைகள். சிறிது நேரம் கழித்து முயலவும்.',
  'Too many searches. Wait a minute, or paste the company ID instead.': 'அதிகமான தேடல்கள். ஒரு நிமிடம் காத்திருக்கவும், அல்லது நிறுவன ID-ஐ ஒட்டவும்.',
  'Too many separate rows are selected. Select ranges, or import every valid row.': 'மிக அதிகமான தனி வரிசைகள் தேர்ந்தெடுக்கப்பட்டுள்ளன. வரம்புகளைத் தேர்ந்தெடுக்கவும் அல்லது எல்லா சரியான வரிசைகளையும் இறக்குமதி செய்யவும்.',
  'Too many bookings, stops or vehicles for one plan. Split it by shift, branch or site.': 'ஒரு திட்டத்திற்கு அதிக முன்பதிவுகள், நிறுத்தங்கள் அல்லது வாகனங்கள். ஷிஃப்ட், கிளை அல்லது தளம் வாரியாகப் பிரிக்கவும்.',
  'At most {{n}} bookings per plan. Split larger groups by shift, branch or site.': 'ஒரு திட்டத்திற்கு அதிகபட்சம் {{n}} முன்பதிவுகள். பெரிய குழுக்களை ஷிஃப்ட், கிளை அல்லது தளம் வாரியாகப் பிரிக்கவும்.',
  'Company maximum ride time: {{value}}': 'நிறுவனத்தின் அதிகபட்ச பயண நேரம்: {{value}}',
  'Company maximum ride time: no limit': 'நிறுவனத்தின் அதிகபட்ச பயண நேரம்: வரம்பு இல்லை',
  'Enter the maximum ride time in minutes (15–240).': 'அதிகபட்ச பயண நேரத்தை நிமிடங்களில் உள்ளிடவும் (15–240).',
  'Give a reason for the override: at least 15 characters, in words.': 'மேலெழுதலுக்கான காரணத்தைக் கொடுக்கவும்: குறைந்தது 15 எழுத்துகள், சொற்களில்.',
  'Leave empty for no limit. 15–240 minutes.': 'வரம்பு இல்லாமல் இருக்க காலியாக விடவும். 15–240 நிமிடங்கள்.',
  'Longest time a passenger may spend in the vehicle. Route optimisation uses it unless a plan has an authorised override.': 'ஒரு பயணி வாகனத்தில் இருக்கக்கூடிய அதிகபட்ச நேரம். ஒரு திட்டத்திற்கு அங்கீகரிக்கப்பட்ட மேலெழுதல் இல்லாவிட்டால், வழி உகப்பாக்கம் இதைப் பயன்படுத்தும்.',
  'Longest time a passenger may spend in the vehicle. Route optimisation is not switched on, so this has no effect until it is.': 'ஒரு பயணி வாகனத்தில் இருக்கக்கூடிய அதிகபட்ச நேரம். வழி உகப்பாக்கம் இயக்கப்படவில்லை, எனவே அது இயக்கப்படும் வரை இதற்கு எந்த விளைவும் இல்லை.',
  'Maximum ride time': 'அதிகபட்ச பயண நேரம்',
  'Maximum ride time (minutes)': 'அதிகபட்ச பயண நேரம் (நிமிடங்கள்)',
  'Maximum ride time for this plan (minutes)': 'இந்தத் திட்டத்திற்கான அதிகபட்ச பயண நேரம் (நிமிடங்கள்)',
  'Maximum ride time saved.': 'அதிகபட்ச பயண நேரம் சேமிக்கப்பட்டது.',
  'Not optimised yet · override set: {{value}}': 'இன்னும் உகப்பாக்கப்படவில்லை · மேலெழுதல் அமைக்கப்பட்டது: {{value}}',
  'Only a Transport admin with whole-company access can change this.': 'முழு நிறுவன அணுகல் உள்ள போக்குவரத்து நிர்வாகி மட்டுமே இதை மாற்ற முடியும்.',
  'Override the company maximum ride time for this plan': 'இந்தத் திட்டத்திற்கு நிறுவனத்தின் அதிகபட்ச பயண நேரத்தை மேலெழுதவும்',
  'Reason for the override': 'மேலெழுதலுக்கான காரணம்',
  'Required: at least {{n}} characters, in words. Recorded in the audit log with your name.': 'கட்டாயம்: குறைந்தது {{n}} எழுத்துகள், சொற்களில். உங்கள் பெயருடன் தணிக்கைப் பதிவில் பதிவு செய்யப்படும்.',
  'Turning this off returns the plan to the company policy at the next optimisation.': 'இதை அணைத்தால், அடுத்த உகப்பாக்கத்தில் திட்டம் நிறுவனக் கொள்கைக்குத் திரும்பும்.',
  '{{value}} · company policy': '{{value}} · நிறுவனக் கொள்கை',
  '{{value}} · override: {{reason}}': '{{value}} · மேலெழுதல்: {{reason}}',
  'Too many videos are playing right now. Close another video and try again.': 'இப்போது பல வீடியோக்கள் இயங்குகின்றன. வேறொரு வீடியோவை மூடிவிட்டு மீண்டும் முயற்சிக்கவும்.',
