  'Track your own vehicle, family members or this phone. For business fleets, contact VeeTrax.': 'உங்கள் வாகனம், குடும்பத்தினர் அல்லது இந்தத் தொலைபேசியைக் கண்காணிக்கவும். வணிக வாகனக் குழுக்களுக்கு VeeTrax-ஐத் தொடர்பு கொள்ளவும்.',
