  'Tracker tamper / GPS jamming': 'டிராக்கர் சேதப்படுத்தல் / GPS ஜாமிங்',
  'Trackers that connected to the gateway but aren\'t registered. Register them to start tracking.': 'கேட்வேயுடன் இணைந்த ஆனால் பதிவு செய்யப்படாத டிராக்கர்கள். கண்காணிப்பைத் தொடங்க அவற்றைப் பதிவு செய்யவும்.',
  'Tracking': 'கண்காணிப்பு',
  'Tracking devices and phones need a yearly licence, bought after you sign in.': 'கண்காணிப்புச் சாதனங்கள் மற்றும் தொலைபேசிகளுக்கு ஆண்டு உரிமம் தேவை, உள்நுழைந்த பின் வாங்கலாம்.',
  'Tracking history': 'கண்காணிப்பு வரலாறு',
  'Tracking started': 'கண்காணிப்பு தொடங்கியது',
