  'Tracking switched on': 'கண்காணிப்பு இயக்கப்பட்டது',
  'Tracks assigned branches/vehicles': 'ஒதுக்கப்பட்ட கிளைகள்/வாகனங்களைக் கண்காணிக்கும்',
  'Transfer {{amount}} to the account below and send us the reference. Your licences are activated and the invoice is e-mailed when the payment is recorded.': 'கீழே உள்ள கணக்கிற்கு {{amount}} அனுப்பி குறிப்பு எண்ணை எங்களுக்கு அனுப்புங்கள். கட்டணம் பதிவானதும் உங்கள் உரிமங்கள் செயல்பட்டு விலைப்பட்டியல் மின்னஞ்சல் செய்யப்படும்.',
