  'Trips': 'பயணங்கள்',
  'Trips already created stay as they are; no new trips are created from this schedule.': 'ஏற்கனவே உருவாக்கப்பட்ட பயணங்கள் அப்படியே இருக்கும்; இந்த அட்டவணையிலிருந்து புதிய பயணங்கள் உருவாக்கப்படாது.',
  'Trips and stops': 'பயணங்கள் மற்றும் நிறுத்தங்கள்',
  'Trips and stops worked out from the positions.': 'இருப்பிடத் தரவிலிருந்து கணக்கிடப்பட்ட பயணங்கள் மற்றும் நிறுத்தங்கள்.',
  'Trips appear here when a route schedule generates them or when you create one.': 'வழித்தட அட்டவணை பயணங்களை உருவாக்கும்போது அல்லது நீங்கள் ஒன்றை உருவாக்கும்போது அவை இங்கே தோன்றும்.',
