  'Trips planned on a route, tracked against their stops and times.': 'ஒரு வழித்தடத்தில் திட்டமிட்ட பயணங்கள், அவற்றின் நிறுத்தங்கள் மற்றும் நேரங்களின்படி கண்காணிக்கப்படும்.',
  'Trips report': 'பயண அறிக்கை',
  'Trips today': 'இன்றைய பயணங்கள்',
  'Trips, daily distance, reports and the History track leave out points the analysis marks as spike, jump, inaccurate, fake GPS or invalid. Switching recalculates the last 7 days; compare first with the clean distance in History → All points.': 'பகுப்பாய்வு ஸ்பைக், தாவல், துல்லியமற்றது, போலி GPS அல்லது செல்லாதது எனக் குறிக்கும் புள்ளிகளைப் பயணங்கள், தினசரி தூரம், அறிக்கைகள் மற்றும் வரலாற்றுப் பாதை தவிர்க்கும். மாற்றினால் கடந்த 7 நாட்கள் மீண்டும் கணக்கிடப்படும்; முதலில் வரலாறு → அனைத்துப் புள்ளிகளில் சுத்தமான தூரத்துடன் ஒப்பிடுங்கள்.',
  'Truck': 'லாரி',
  'Try': 'முயற்சிக்கவும்',
  'Try a different search or clear the filters.': 'வேறு தேடலை முயலவும் அல்லது வடிகட்டிகளை அழிக்கவும்.',
  'Try a longer period or a wider scope.': 'நீண்ட காலம் அல்லது பரந்த வரம்பை முயலவும்.',
  'Try a wider date range or clear the filters.': 'பரந்த தேதி வரம்பை முயலவும் அல்லது வடிகட்டிகளை அழிக்கவும்.',
  'Try again': 'மீண்டும் முயற்சிக்கவும்',
  'Try another day or a longer range.': 'வேறு நாள் அல்லது நீண்ட வரம்பை முயலவும்.',
  'Try another search or status.': 'வேறு தேடல் அல்லது நிலையை முயலவும்.',
  'Try clearing the search or filters.': 'தேடல் அல்லது வடிகட்டிகளை அழித்துப் பார்க்கவும்.',
  'Try one of these': 'இவற்றில் ஒன்றை முயற்சிக்கவும்',
  'Tue': 'செவ்',
  'Turn it on in Settings and choose the work-site geofences.': 'அமைப்புகளில் இயக்கி, பணித்தள ஜியோஃபென்ஸ்களைத் தேர்ந்தெடுக்கவும்.',
  'Turn it on in the web app: Staff attendance → Settings.': 'இணையச் செயலியில் இயக்கவும்: பணியாளர் வருகை → அமைப்புகள்.',
  'Turn off Battery saver in the quick settings': 'விரைவு அமைப்புகளில் பேட்டரி சேவரை அணைக்கவும்',
  'Turn off Battery saver, or set its location option to keep location on': 'பேட்டரி சேமிப்பை அணைக்கவும், அல்லது அதன் இருப்பிட விருப்பத்தில் இருப்பிடத்தை இயக்கத்தில் வைக்கவும்',
  'Turn off critical alert pop-ups': 'அவசர எச்சரிக்கை பாப்-அப்களை அணை',
  'Turn off to archive the route. Archived routes are kept with their trips.': 'வழித்தடத்தைக் காப்பகப்படுத்த அணைக்கவும். காப்பகப்படுத்திய வழித்தடங்கள் அவற்றின் பயணங்களுடன் வைக்கப்படும்.',
  'Turn off to choose branches, groups or vehicles': 'கிளைகள், குழுக்கள் அல்லது வாகனங்களைத் தேர்ந்தெடுக்க அணைக்கவும்',
  'Turn off voice announcements': 'குரல் அறிவிப்புகளை அணை',
  'Turn on "Override Do Not Disturb" for SOS / Emergency so the siren rings even when the phone is on Do Not Disturb.': 'SOS / அவசரம் என்பதற்கு "தொந்தரவு செய்ய வேண்டாம் என்பதை மீறு" என்பதை இயக்கவும்; அப்போது ஃபோன் தொந்தரவு செய்ய வேண்டாம் பயன்முறையில் இருந்தாலும் சைரன் ஒலிக்கும்.',
