  'UPI: check the UTR and amount on your bank / UPI statement. Cash: confirm once the cash is in hand.': 'UPI: உங்கள் வங்கி / UPI அறிக்கையில் UTR மற்றும் தொகையைச் சரிபார்க்கவும். ரொக்கம்: பணம் கைக்கு வந்ததும் உறுதிப்படுத்தவும்.',
