  'Use +91… format': '+91… வடிவத்தைப் பயன்படுத்தவும்',
  'Use 1 vehicle': '1 வாகனத்தைப் பயன்படுத்து',
  'Use 4–32 letters, digits, - or _': '4–32 எழுத்துகள், எண்கள், - அல்லது _ பயன்படுத்தவும்',
