  'Use the IMEI and claim code from the help sheet in the box, or a tracker you bought elsewhere.': 'பெட்டியில் உள்ள உதவித் தாளின் IMEI மற்றும் உரிமைக் குறியீட்டைப் பயன்படுத்தவும், அல்லது வேறு இடத்தில் வாங்கிய டிராக்கரை.',
  'Use the new password next time you sign in.': 'அடுத்த முறை உள்நுழையும்போது புதிய கடவுச்சொல்லைப் பயன்படுத்தவும்.',
  'Use this signing secret to verify the X-VeeTrax-Signature header. You can view or rotate it later.': 'X-VeeTrax-Signature தலைப்பைச் சரிபார்க்க இந்த கையொப்ப ரகசியத்தைப் பயன்படுத்தவும். பின்னர் பார்க்கலாம் அல்லது மாற்றலாம்.',
  'Use this when the driver has set off (for example, after a call). Boarding is still recorded per passenger.': 'ஓட்டுநர் புறப்பட்டதும் (எ.கா. அழைப்புக்குப் பின்) இதைப் பயன்படுத்தவும். ஏறுதல் இன்னும் ஒவ்வொரு பயணிக்கும் தனியாகப் பதிவாகும்.',
  'Use vehicle location': 'வாகன இருப்பிடத்தைப் பயன்படுத்து',
  'Use with a road distance objective; 0 to ignore distance.': 'சாலைத் தூர நோக்கத்துடன் பயன்படுத்தவும்; தூரத்தைப் புறக்கணிக்க 0.',
