  'We are the provider': 'நாங்கள் வழங்குநர்',
  'We can hear this tracker. Choose its model to add it.': 'இந்த டிராக்கர் எங்களுக்குக் கிடைக்கிறது. சேர்க்க அதன் மாடலைத் தேர்ந்தெடுக்கவும்.',
  'We check the payment and activate your licences, usually within a few hours. The GST invoice is emailed to you.': 'கட்டணத்தைச் சரிபார்த்து உங்கள் உரிமங்களைச் செயல்படுத்துவோம், பொதுவாக சில மணிநேரங்களில். GST விலைப்பட்டியல் உங்களுக்கு மின்னஞ்சல் செய்யப்படும்.',
  'We send a 6-digit code by SMS to their phone. Ask them for it: that is their consent to be tracked.': 'அவர்களின் ஃபோனுக்கு SMS மூலம் 6 இலக்கக் குறியீட்டை அனுப்புகிறோம். அதைக் கேளுங்கள்: அதுவே கண்காணிக்கப்பட அவர்களின் ஒப்புதல்.',
  'We sent a 6-digit code to {{email}}. It expires in 10 minutes.': '{{email}}-க்கு 6 இலக்கக் குறியீட்டை அனுப்பியுள்ளோம். இது 10 நிமிடங்களில் காலாவதியாகும்.',
  'We\'ll send a 6-digit code to this number.': 'இந்த எண்ணுக்கு 6 இலக்கக் குறியீட்டை அனுப்புவோம்.',
  'We\'ll send a 6-digit code to verify it.': 'சரிபார்க்க 6 இலக்கக் குறியீட்டை அனுப்புவோம்.',
